/* Опубликованные отзывы покупателей из Битрикса (инфоблок 13), без e-mail и телефонов. Собран tools/build_brand_data.py, руками не править. */
window.AS_REVIEWS = [{"b":"chevrolet","f":"chevrolet-rezzo","n":"Евгений","c":"Кемерово","d":"26.06.2022","t":"У меня шевроле реззо, чехлы искал долго. В автомагазинах на такую машину не подбереш чехлов. На али экспресс тоже нет. Заказал в 1авточехол. Обалденные чехлы. Ну пришлось седушки снимать. Спасибо вашей фирме.","car":"Шевроле реззо","ph":["iblock/eb3/IMG_20220625_091246.jpg","iblock/43e/IMG_20220625_091230.jpg","iblock/3aa/IMG_20220625_091214.jpg"]},{"b":"chevrolet","f":"chevrolet-niva","n":"Петр","c":"Улан-Удэ","d":"12.06.2022","t":"Мне нужно было только 2 передних чехла, их и заказал. Без проблем обговорили с менеджером цвет и текстуру чехлов. Установил чехлы самостоятельно, для удобства установки снимал сиденья с автомобиля, отсоединял спинку от подушки, надевал и подгонял чехлы, собирал сиденья и возвращал на место. Единственное затруднение вызвало соединение нижних лент велкро на спинках, они почти не доставали друг до друга. Пришлось применить силу. Собственно, и всё.\nВ заключение скажу - мне пошили отличные чехлы, я доволен качеством материала и изготовления, надеюсь они прослужат долго.","car":"Нива Шевроле","ph":["iblock/22b/1.jpg","iblock/f3a/I2.jpg","iblock/36c/3.jpg","iblock/7c0/4.jpg"]},{"b":"toyota","f":"toyota-noah","n":"Сергей","c":"Лесосибирск","d":"15.05.2022","t":"Работой компании доволен. Чехлы изготовили, доставили быстро. Качество работы хорошее. Сели идеально. Спасибо. Очень рад, что наши российские компании работают так хорошо, качественно.","car":"Тойота ноах гибрид"},{"b":"toyota","f":"toyota-land-cruiser-prado","n":"Андрей","c":"Петропавловск-Камчатский","d":"10.05.2022","t":"Заказал повторно. Качество отличное. Хватило на 6 лет!!! Чехлы крепкие, отлично сшиты. Рекомендую!!!","car":"Prado"},{"b":"nissan","f":"nissan-x-trail","n":"Игорь","c":"Москва","d":"07.05.2022","t":"Заказал чехлы для своей машины и остался очень доволен качеством.Огромное спасибо за качественный сервис и работу.Буду рекомендовать знакомым и друзьям.","car":"Nissan X-Trail"},{"n":"Евгений","c":"Иркутск","d":"15.04.2022","t":"Всё хорошо подошло!!! Рекомендую данное ателье!!! Спасибо за качество!!!"},{"b":"toyota","f":"toyota-voltz","n":"Евгений","c":"Железногорск-Илимский","d":"14.04.2022","t":"Нашел, заказал, получил, поставил! Приятно) Большое спасибо. Вы на высоте. 5+","car":"Тойота Вольтц"},{"b":"chery","f":"chery-tiggo","n":"Сергей","c":"Будённовск","d":"05.04.2022","t":"Отличные чехлы!!!! Всем рекомендую, только положительные эмоции.","car":"Черри Тогго Т-11 2012","ph":["iblock/27b/IMG_20220327_154608.jpg"]},{"b":"mitsubishi","f":"mitsubishi-montero","n":"Юрий","c":"Куйтун Иркутская обл.","d":"15.03.2022","t":"Качество супер. Огромное спасибо.","car":"Mitsubishi Montero"},{"b":"toyota","n":"Юлия","c":"Новосибирск","d":"24.02.2022","t":"Качественные чехлы. Не везде есть отверстия и что бы их надеть, пришлось вытаскивать кресла с машины, очень трудоемкий процесс. Но не жалею, салон как новенький. Рекомендую.","car":"Тайота Гая","ph":["iblock/3f4/1.jpg","iblock/9e2/3.jpg","iblock/5cf/2.jpg"]},{"b":"nissan","f":"nissan-leaf","n":"Алексей","c":"Симферополь","d":"21.02.2022","t":"1. Не ожидал найти чехлы на Ниссан лиф - тут они есть.\n2. Насчёт доставки в Крым были особые сомнения - все для людей, доставили.\n3. Оплата при получении есть!\n4 и самое главное. Чехлы сели отлично! Швы и прорези на своих местах, качество изготовления очень и очень хорошее! \nКачество материала не первый взгляд нормальное, время покажет его ресурс.\nСалон машины стал уютней, ухаживать за сиденьями стало проще.","car":"Nissan Leaf","ph":["iblock/a95/IMG_20220220_145949.jpg"]},{"b":"mitsubishi","f":"mitsubishi-lancer","n":"александр","c":"Улан-Удэ","d":"27.01.2022","t":"Заказываю уже 3 чехлы без проблем отхаживают 5 лет.Эксплуатирую ежедневно круглый год качество отличное швы не рвутся единственное эко кожа начинает трескаться на 3 год.Крайний раз получил все в комплекте единственный недостаток маломерит подлокотник и лишнее отверстии на задней спинке и нет под аэрбеги на передних сидения нет утончения на старых заказах всегда делали.Спасибо качество как всегда.","car":"ммс Lancer x"},{"b":"toyota","f":"toyota-corolla-fielder","n":"Евгений","c":"Мыски","d":"21.01.2022","t":"Чехлы класс. Подошли как родные. На следующий авто буду заказывать тут же.","car":"Тайота королла филдр"},{"b":"nissan","f":"nissan-x-trail","n":"Евгений","c":"Феодосия","d":"20.01.2022","t":"Хочу поблагодарить за отличную работу, нигде не мог найти чехлы на заднее сидение без подлокотника, договорились, пошили как оригинальные, сели на сидения как родные. Доставка в Крым относительно быстро. Спасибо за вашу работу.","car":"Nissan x-trail"},{"b":"nissan","f":"nissan-leaf","n":"Дарья","c":"Благовещенка","d":"14.01.2022","t":"Чехлы просто супер, очень качественные и красивые, заказывали в цвете алькантара и экокожа под цвет.В подарок пришла подушечка подголовник и оплётка на руль.Еще не одевали,но думаю,что все подойдёт идеально, предусмотрено до мелочей))) Огромное спасибо!!!Это лучшие чехлы,что были у нас на всех машинах.","car":"Ниссан Лиф"},{"b":"honda","f":"honda-fit","n":"Илья","c":"Якутск","d":"13.01.2022","t":"Спасибо, все подошло как родное. Однозначно рекомендую","car":"Хонда фит"},{"b":"toyota","f":"toyota-passo","n":"Инна","c":"Чита","d":"09.01.2022","t":"На мой авто Toyota Passo чехлы купить оказалось просто невозможным! Ваше ателье просо чудо! Спасибо Вам огромное за четкую работу, качество пошива, и ту радость, которую вы дарите своим заказчикам!","car":"Toyota Passo"},{"b":"toyota","f":"toyota-corolla","n":"Данила","c":"Воронеж","d":"05.01.2022","t":"Спасибо за качественный пошив чехлов. Установил за пару часов, все подошло как родное, хорошие материалы, отличный пошив, хорошое обслуживание. Приятный подарок к новому году подушка и оплётка на руль хорошего качества. Спасибо!","car":"Toyota Corolla 120","ph":["iblock/772/1482BAF2-6C84-4707-A901-D011AD12E463.jpeg","iblock/d16/5DC4288A-F03F-4587-B260-EE3FE6AB3CF7.jpeg","iblock/831/E192759D-87C3-48E0-B63B-5DCDCB72C062.jpeg","iblock/6d1/2D00BD7F-6E01-41CB-9072-6E1243EC1BFA.jpeg"]},{"b":"toyota","f":"toyota-aqua","n":"Николай","c":"Тюмень","d":"28.09.2021","t":"Большое спасибо! Все подошло идеально.Чехлы на сиденья устанавливаются как заводские.По коврикам в салон, три года назад заказывал в Москве (другая фирма) на Приус, так они даже были не симметричны, полученные коврики сделаны идеально,качественно и очень красиво. Спасибо вашим специалистам.","car":"Тойота Аква"},{"b":"toyota","f":"toyota-prius-prius-a","n":"Руслан","c":"Красноярск","d":"06.06.2021","t":"Спасибо за работу , подошло идеально. Всем рекомендую ателье.","car":"Тойота Приус Альфа"},{"b":"toyota","f":"toyota-vitz","n":"Надежда","c":"Свердловская область,г.Среднеуральск","d":"04.05.2021","t":"Огромное спасибо Вашей компании!!! Очень оперативно приняли заказ, очень качественно сшили чехлы,как родные,спасибо!Выполнили в срок,удобная доставка!Отдельное спасибо Юлии!Все четко и понятно,а главное всегда на связи!!!Спасибо Вам всем огромное!!!!","car":"Тойота Витц"},{"b":"toyota","f":"toyota-corolla","n":"Оксана","c":"Новосибирская область","d":"03.05.2021","t":"Заказывала чехлы из экокожи. Чехлы выполнены качественно. Спасибо.","car":"Toyota Corolla 9"},{"b":"toyota","f":"toyota-probox","n":"Татьяна","c":"Красноярск","d":"21.04.2021","t":"Редко пишу отзывы, но вот собираюсь заказывать снова чехлы именно у вас, поэтому и решила добавить свой отзыв. Качество действительно отличное. Брала из экокожи. Очень достойное качество материала и пошив. Два года , а как новые. Сейчас буду заказывать на новое авто.","car":"TOYOTA PROBOX"},{"b":"skoda","f":"skoda-roomster","n":"Юрий","c":"Тюмень","d":"15.04.2021","t":"Спасибо большое, очень понравились ваши чехлы из экокожи на Шкоду Румстер. Быстрая доставка. Установил за 2 часа. даже не снимая сиденья. Все подошло, сшито все точно, чехлы сели как заводские.","car":"Skoda Roomster"},{"b":"toyota","f":"toyota-prius","n":"Олег","c":"Чита","d":"14.04.2021","t":"Заказываю в Автостиле второй раз. Почти год ждал пока сделают лекала на Приус 50. Дождался! Работают ребята быстро и четко. Можно заказать различные комбинации материалов, есть из чего выбирать. Чехлы сшиты на отлично, четко повторяют все контуры сидений! Перед надеванием запаситесь терпением и 2-3 часами свободного времени. Тем у кого за центнер веса лучше позвать помощника. В общем респект фирме и их изделиям!!!","car":"Toyota Prius IV"},{"b":"toyota","f":"toyota-prius-prius-a","n":"Андрей","c":"Чита","d":"09.04.2021","t":"Чехлы пришли вовремя, транспортной компанией, пошиты качественно, я доволен! Рекомендую всем!Спасибо вам большое!","car":"Toyota Prius a"},{"b":"honda","f":"honda-fit","n":"Наталья","c":"Чегдомын, Хабаровский край","d":"06.04.2021","t":"хорошее качество, сели идеально, спасибо","car":"Fit 2017"},{"n":"Андрей","c":"Чита","d":"05.04.2021","t":"Заказал чехлы черные с шоколадом, пришли вовремя, подошли идеальн! Спасибо вам!","ph":["iblock/4e4/IMG_20210327_144641.jpg","iblock/04f/IMG_20210327_144628.jpg"]},{"b":"toyota","f":"toyota-vitz","n":"Елена","c":"Ставрополь","d":"04.04.2021","t":"В конце прошлого года заказала чехлы в фирме автостиль,но в связи с погодными условиями, одеть их удалось только вчера. Хочу сказать большое спасибо всем сотрудникам принимавшим участие в изготовлении моих чехлов! Качество на высоте! Сели как влитые! Я очень довольна! Успехов вам и процветания! Рекомендую однозначно!","car":"Toyota vitz"},{"b":"honda","f":"honda-stepwgn","n":"Виктор","c":"Барнаул г.","d":"02.04.2021","t":"РЕКОМЕНДУЮ. Вежливые, все обьяснили, всегда выходили на связь по моим вопросам, заказ сделали вовремя, претензий нет, сделали качественно-красиво.Рекомендую","car":"Хонда стэп вагон 2009"},{"b":"toyota","f":"toyota-premio","n":"Людмила","c":"Комсомольск-На-Амуре","d":"16.02.2021","t":"Спасибо за работу. Заказ выполнен в указанные сроки. Доставка вовремя, своевременное оповещение. Чехлы качественно сшиты, строчка ровная. Еще раз спасибо.","car":"тойота премия"},{"b":"nissan","f":"nissan-leaf","n":"Надежда","c":"Железногорск-Илимский","d":"10.02.2021","t":"Всем привет, пол года назад заказала на ниссан лиф чехлы из экокожи. От чехлов полный восторг, оделись легко, не вышаркиваются, смотрятся стильно и дорого. Цена меня очень порадовала, не дорого! Спасибо магазину.","car":"Nissan Life"},{"b":"ssangyong","f":"ssangyong-korando","n":"Александр","c":"Якутск","d":"14.01.2021","t":"Благодарю за работу.отличные чехлы.всё точно.Спасибо","car":"Ssang Yong Korando"},{"b":"toyota","f":"toyota-ipsum","n":"Азиана","c":"Кызыл","d":"01.12.2020","t":"Сегодня получили свои чехлы , все подошло, лайк лайк! Огромное спасибо за вашу работу, за честность и ответственность! Успехов !","car":"Ипсум","ph":["iblock/1a6/20201201_142528.jpg"]},{"b":"toyota","f":"toyota-corolla-fielder","n":"александр","c":"Горно Алтайск","d":"18.09.2020","t":"третий раз пользуюсь услугами автостиль все отлично сегодня получил чехлы и коврики .коврики очень красиво как влитые ни одного зазора думаю и чехлы такого же качества спасибо большое","car":"филдер"},{"b":"mitsubishi","f":"mitsubishi-pajero","n":"Александр","c":"пгт. Забайкальск","d":"16.07.2020","t":"Все подошло, отличное качество рекомендую.","car":"Mitsubishi Pajero"},{"b":"toyota","f":"toyota-vitz","n":"Дарья","c":"Екатеринбург","d":"06.07.2020","t":"Спасибо большое магазину и изготовителям этих классных чехлов. Подошли идеально, плотно облегают сидения и смотрятся, как заводские. Муж, когда устанавливал, все хвалил и хвалил качество. Чехлы в экокоже смотрятся шикарно!","car":"Тойота Витц 2003 г.в."},{"b":"honda","f":"honda-fit","n":"Александр","c":"Комсомольск-на-Амуре","d":"29.06.2020","t":"Заказ №24503. За скромную цену заказал/получил модельные чехлы, конкретно для своего авто с учётом всех нюансов сидений, качество пошива 4+ достаточно качественно. Не советую покупать в магазинах шаговой доступности универсальные чехлы с небольшой экономией и безобразной посадкой на сидениях. Благодарю сотрудников АВТОСТИЛЬ, и рекомендую всем....мои друзья уже заинтересованы в заказе чехлов по критерию цена/качество.","car":"Honda Fit III Hybrid 2014"},{"b":"toyota","f":"toyota-land-cruiser-prado","n":"виктор","c":"Елизово","d":"07.06.2020","t":"Заказывал на Прадо 150. Чехлы как заводские. Сели идеально. Спасибо за мастерство и порядочность. Менеджер перезвонила, все уточнила. Цвет заказал бежевый. Хорошо подошли к цвету машины - белый перламутр. Одели сами и без инструкции. Рекомендую. Хорошо если бы все продавцы были такие. Всем удачи.","car":"Ленд Крузер Прадо 150"},{"b":"honda","f":"honda-vezel","n":"Сергей","c":"Хабаровск","d":"25.05.2020","t":"Хочу выразить огромную признательность и спасибо за ваш продукт. Сегодня забрал свои чехлы.Получил то что просил-заказывал.Сели отлично ,немного не разобрался с передними сиденьями.Но это не глобально.Удачи и процветания.","car":"Honda Vezel"},{"b":"toyota","n":"Алексей","c":"Белгород","d":"21.04.2020","t":"Заказал чехлы экокожа модельные , изготовили очень быстро! Установил сели как родные все аккуратно сшито + подарок оплётка на руль тоже идеально подошла. СПАСИБО ЗА КАЧЕСТВО И ОПЕРАТИВНОСТЬ.","car":"Тойота Королла  nze 121","ph":["iblock/5e1/20200421_081731.jpg"]},{"b":"toyota","f":"toyota-corolla-fielder","n":"Владимир","c":"Шимановск","d":"15.04.2020","t":"Получили чехлы, все подошло идеально, просто","car":"Тойота корола филдер"},{"b":"subaru","f":"subaru-legacy-b4","n":"Олег","c":"Южно-Сахалинск","d":"01.03.2020","t":"Спасибо, подошло на все 100!","car":"subaru legacy B4","ph":["iblock/832/IMG-20200301-WA0006.jpeg"]},{"b":"mazda","f":"mazda-cx-5","n":"Илья","c":"Томск","d":"26.02.2020","t":"Выражаю благодарность компании Автостиль за оперативно выполненный заказ! Чехлы подошли очень хорошо, смотрятся тоже достойно. Качество мне понравилось!","car":"Мазда СХ-5"},{"b":"toyota","f":"toyota-corolla-fielder","n":"Варю","c":"Верхневилюйск","d":"23.02.2020","t":"Вчера получила свой заказ :) И очень довольна качеством, цветом и пошивом мастеров своего дела, честно сказать сперва сомневалась отправят ли вообще, или будет ожидание и реальность. Но получив свой чехол сразу влюбилась, сидят как родные нигде не торчат. Вообщем заказывайте и пользуйтесь с удовольствием :)))))","car":"Тойота Филдер"},{"b":"renault","f":"renault-duster","n":"Николай Сапего","c":"пгт. Зеленоборский, Мурманская обл.","d":"01.02.2020","t":"Всем доброго времени суток! Хочу выразить искреннюю благодарность коллективу компании \"АВТОСТИЛЬ\" за выполненный заказ! 11.01.20 приняли мой заказ на пошив чехлов, а сегодня, 01.02.20 я их получил. Хотя надо сказать, что еще вчера,31.01.20 посылка прибыла в почтовое отделение. Занес домой, вскрыл... Комплект полный, сделан качественно, цветовая гамма как заказывал, оплетка на руль в подарок, как и обещали!!! Очень умилило, что даже нитки с иголкой приложили к оплетке :))! Спасибо Большое)). Сейчас еще холодно, займусь установкой чехлов ближе к лету...Всем добра и здоровья! P.S. Летом сфотографирую и дополню отзыв, надеюсь.","car":"RENAULT DUSTER 2017 г. в."},{"b":"ssangyong","f":"ssangyong-kyron","n":"Ирина","c":"Находка, Приморский край","d":"29.01.2020","t":"В ноябре 2019 года получила чехлы из эко-кожи хорошего качества, пошив отличный, нитки нигде не торчат, швы ровные. В полном объеме удалось надеть их за 2,5 часа мучений - но оно того стоило. Подошли почти все отверстия в чехлах (не было только прорези для рукоятки регулировки поясничного упора водителя), чехлы сели на сиденья как влитые, салон стал выглядеть дорого. Через два месяца придраться не к чему, чехлы приняли форму окончательно, нигде ничего не растянулось и не порвалось. Спасибо за приятное сотрудничество и быстрые сроки изготовления!","car":"SsangYong Kyron, 2011 года"},{"b":"hyundai","f":"hyundai-solaris","n":"Дмитрий","c":"Кыштым","d":"28.01.2020","t":"Спасибо большое за чехлы. Изготовили быстро и качественно. Вежливый консультант. Все доступно рассказали объяснили.","car":"Hyundai solaris"},{"b":"peugeot","f":"peugeot-308","n":"Наида","c":"Ахтубинск","d":"26.12.2019","t":"Добро времени суток! Хочу оставить свой отзыв о чехлах. Честно говоря, я очень сомневалась, что чехлы будут соответствовать моим ожиданиям (ни раз обжигалась об такие сайты). Однако, получив чехлы, я была поражена качеством и тем, что они идеально подошли к сиденьям моего автомобиля. Моей радости не было предела. Очень красиво и качественно! Отдельное спасибо за быструю доставку!!!! Все идеально!!!","car":"Peugeot 308"},{"b":"honda","f":"honda-fit","n":"Александр","c":"Комсомольск-на-Амуре","d":"11.12.2019","t":"Большое спасибо за выполненную работу. Чехлы подошли, как родные сели, все аккуратно по размеру. Цена тоже порадовала. Возможно буду заказывать еще.","car":"Honda Fit II 2008","ph":["iblock/088/6ba45164-e724-4f19-b400-b9b6685b7e5e.jpg","iblock/85c/c1643a44-00f7-47a6-b1cc-3d2b48b6de92.jpg"]},{"b":"toyota","f":"toyota-rav4","n":"Александр","c":"Биробиджан, ЕАО, Россия","d":"30.11.2019","t":"Хочу поблагодарить за чехлы. Сшили за 3 рабочих дня как и обещали. Качество отличное, сели как влитые, пришли даже раньше, чем обещала транспортная компания, чем очень порадовали. Девчата-менеджеры вежливые. Спасибо огромное всему коллективу за отличную работу. Китайское барахло надоело, здорово,что нашли вас в интернете и очень сильно помогли отзывы. Рекомендую, заказывайте и не пожалеете","car":"RAV 4"},{"b":"honda","f":"honda-cr-v","n":"александр","c":"йошкар-ола","d":"14.11.2019","t":"Заказал чехлы пришли быстро ,всем большое спасибо ,чехлы отлично сели\nочень доволен .Переживал поначалу но все очень хорошо молодцы.\n14.11.19г. александр г Йошкар-Ола Honda CR--2005G","car":"honda cr-v 2005g"},{"b":"hyundai","f":"hyundai-creta","n":"Головина Анастасия Григорьевна","c":"Новосибирск","d":"11.11.2019","t":"Светлана, добрый день! Хочу поблагодарить Вас за чехлы. Недавно заказывала у Вас чехлы на Крету. Чехлы супер!)","car":"Hyundai Creta"},{"b":"toyota","f":"toyota-probox","n":"Аена","c":"Северск","d":"29.10.2019","t":"Чехлы отличные, сели идеально. Пошив отличный!!! Рекомендую, лучше подождать, чем купить на рынке универсальные. Где все торчит и ничего не подходит.","car":"Тойота пробокс"},{"b":"honda","f":"honda-fit","n":"Грушевский Дмитрий","c":"Петропавловск-Камчатский","d":"30.09.2019","t":"В очередной раз убеждаюсь что у вас работают первоклассные специалисты чехлы подошли как родные всё добротно и красиво спасибо вам и всему коллективу. С уважением Дмитрий","car":"Honda Fit 3"},{"b":"kia","f":"kia-ceed","n":"Анатолий","c":"Заполярный,Мурманской области","d":"05.09.2019","t":"Чехлы отличного качества!!!Нитки не торчат,швы ровные,материал на ощупь очень приятный!!!Установлю отправлю фотоотчёт!!!","car":"Kia See'd"},{"b":"mitsubishi","f":"mitsubishi-outlander","n":"Ирина","c":"Нижневартовск","d":"04.09.2019","t":"Чехлы просто замечательные, сели как родные. Я очень рада, что заказала именно здесь, очень быстрая доставка и вежливый персонал.","car":"Mitsubishi Outlender"},{"b":"mitsubishi","f":"mitsubishi-outlander","n":"Роман","c":"Южный Сахалин","d":"19.08.2019","t":"Аут 2006 года. Правый руль. Японский. Всё подошло. Проблем пока не увидел. Только проблема одна. Долго до Сахалина посылка шла. А так всё ровно.","car":"Митсубиши аутлендр xl","ph":["iblock/59a/Screenshot_20190820-002017.png","iblock/10c/Screenshot_20190820-002043.png","iblock/7db/Screenshot_20190820-002127.png"]},{"b":"toyota","f":"toyota-ipsum","n":"Тимур","c":"Ханты-Мансийск","d":"29.07.2019","t":"Чехлы подошли класс!!! Заказывал давно, но установил в этом году и очень рад, красота! Спасибо. Советую.","car":"toyota ipsum"},{"b":"nissan","f":"nissan-note","n":"Павел","c":"Нижневартовск","d":"27.06.2019","t":"Спасибо вашей фирме за качество, и подход к клиентам!..\nЭто тот самый случай, когда по прошествии времени понимаешь что сделал правильный выбор. \nЗаказывал чехлы в апреле 2017 года, пришли вовремя, при перетяжке салона проблем не возникло никаких... все подошло и село идеально.\nПрошло время, на дворе 2019 год, качество материалов говорит само за себя... ничего не вытерлось, не порвалось, не съехало! В машине каждый день перевожу детей (мы многодетная семья), то есть салон эксплуатируется нещадно... чехлы реально выручают.\nВообщем советую всем... особенно северным регионам, в морозы материал не дубеет и не трескается как у многих других производителей.","car":"nissan note 2008"},{"b":"kia","f":"kia-rio","n":"сергей","c":"Kiselevsk","d":"11.06.2019","t":"НЕ ОЖИДАЛ, МОЛОДЦЫ!!! ПРЕКРАСТНЫЕ СПЕЦИАЛИСТЫ!!! СОВЕТУЮ!!!","car":"кия рио3"},{"b":"nissan","f":"nissan-note","n":"Руслан","c":"Благовещенск","d":"07.06.2019","t":"Качество чехлов отличное!!! Заказ оформили оперативно, учли все тонкости и пожелания, в сроки уложились, доставили быстро ТК DPD. Пожелание на будущее, добавьте двойную строчку по периметру чехлов, смотрелось бы намного эффектнее. Спасибо за качество товара!","car":"Nissan Note E12","ph":["iblock/2f0/20190606_175638_compress75.jpg","iblock/035/20190606_193125_compress1.jpg","iblock/b2d/20190606_084232_compress4.jpg","iblock/0bd/20190606_084223_compress58.jpg","iblock/9e9/20190605_120201_compress49.jpg","iblock/e45/20190606_175055_compress61.jpg","iblock/d92/20190606_154210_compress58.jpg","iblock/f9b/20190606_154130_compress78.jpg","iblock/3fb/20190606_084238_compress84.jpg","iblock/e86/20190604_163225_compress94.jpg","iblock/160/20190606_175206_compress55.jpg","iblock/ba1/20190606_175026_compress53.jpg"]},{"b":"lifan","f":"lifan-x60","n":"Юрий","c":"Северобайкальск","d":"07.06.2019","t":"\" Чехлы подошли очень хорошо.Заказ пришёл быстро,а остальное написано ранее.Спасибо за качество!\"","car":"Lifan X60 2017г."},{"b":"subaru","f":"subaru-forester","n":"Никита","c":"Иваново, Ярославль","d":"31.05.2019","t":"Именно то качество которое хотелось! 2й год интенсивной эксплуатации а им хоть бы что, летом пот рекой не течет (перфорированная экокожа), в -30 не трескается, царапин и задиров от кепок на одежде не остается. Установились чуть хуже чем если бы заказывал перетяжку в ателье. Китай раньше менял раз в год, а тут даже повода нет хоть как то салон обновить). На рабочую альмеру тоже здесь же заказывал и тоже никаких проблем в эксплуатации.","car":"Forester"},{"b":"hyundai","f":"hyundai-creta","n":"Дмитрий","c":"Калининград","d":"28.05.2019","t":"Приобрел чехлы уже на четвертую машину. Качеством очень доволен, за 5 лет никаких проблем нет, чехлы как новенькие. Лекалы отменные, чехлы садятся, как надо. Большое человеческое спасибо мастерам.","car":"Хундай Крета, КИА РИО, КИА Церато, КИА Спортейдж."},{"b":"hyundai","f":"hyundai-solaris","n":"Любовь","c":"Зеленогорск Красноярский край","d":"26.05.2019","t":"Спасибо! Чехлы получили. Все подошло, сидят как влитые. благодарю работников фирмы за внимание и отличную работу.","car":"Hyundai Solaris"},{"b":"hyundai","f":"hyundai-creta","n":"Андрей","c":"Тулун","d":"20.05.2019","t":"Много писать не буду и так всё ясно, качество просто отличное! Авто Hunday Creta 18г. Чехлы сели как родные, все отверстия все прорези на месте. Под заказ сделали синюю строчку. Заказ оплатил сразу по собственному соображению. Доставка Dpd в офис Связного. Спасибо за качество товара!","car":"Hunday Creta","ph":["iblock/285/DSC05442.JPG","iblock/92b/DSC05444.JPG","iblock/d6a/DSC05440.JPG","iblock/280/DSC05443.JPG","iblock/3ed/DSC05447.JPG","iblock/690/DSC05443.JPG","iblock/6ca/DSC05446.JPG"]},{"b":"toyota","f":"toyota-corolla-fielder","n":"Сергей","c":"Благовещенск","d":"11.05.2019","t":"Хочу поблагодарить работников фирмы. Заказал чехлы пошили быстро .Хорошее качество ,прекрасно сидят, легко оделись все прекрасно. Большое вам человеческое спасибо. Буду рекомендовать своим товарищам.","car":"Toyota Corolla Fielder 2014","ph":["iblock/a5d/IMG_1964.JPG","iblock/c84/IMG_1965.JPG","iblock/307/IMG_1966.JPG"]},{"b":"toyota","f":"toyota-ipsum","n":"Дмитрий","c":"Асино","d":"05.05.2019","t":"Большое спасибо получил чехлы на свой ipsum 96г всё отлично подошло, будет следующий авто закажу в Авто стиле.","car":"Toyota ipsum"},{"b":"nissan","f":"nissan-x-trail","n":"Александр","c":"Заозерный","d":"07.04.2019","t":"Заказывал чехлы на ниссан х-треил пришли быстро подошло все идеально . я всем доволен качеством и ценой,персонал вежлив огромное спасибо . буду вас всем рекомендовать","car":"nissan x-treil"},{"b":"toyota","f":"toyota-rav4","n":"любовь","c":"Змеиногорск","d":"04.04.2019","t":"Хорошая работа.Чехлы подошли очень хорошо.Спасибо.","car":"РАФ 4"},{"b":"toyota","n":"Екатерина","c":"Магадан","d":"25.03.2019","t":"Хочу поблагодарить вас за отличную работу. Чехлы пошиты качественно и в указанные сроки. Чехлы сели идеально, смотрятся просто супер! Цвет заказывала - белый (хоть и маркий, но рекомендую!) Спасибо менеджеру за внимательное отношение и индивидуальный подход!","car":"Toyota Land Cruiser 150"},{"b":"tagaz","f":"tagaz-tager","n":"Анатолий","c":"Кострома","d":"24.03.2019","t":"(( спасибо за работу. Заказывал у вас чехлы всё подошло и очень красиво и главное очень всё опеоативно.Так держать!!","car":"тагаз-тагер"},{"b":"toyota","f":"toyota-allion","n":"Эрдыни","c":"Улан-Удэ","d":"18.03.2019","t":"Чехлы очень качественные, подошли идеально, смотрятся круто","car":"Allion"},{"b":"toyota","f":"toyota-corolla","n":"Елена","c":"Бурла","d":"15.03.2019","t":"Хочу поблагодарить вас за отличную работу. Заказывала у вас чехлы. Очень мне понравились. Красивые, качественно сшиты. К тому же дешевле чем везде. И менеджер тоже молодец (приятная, вежливая девушка). Ещё раз спасибо.","car":"Тайота королла"},{"b":"honda","f":"honda-fit","n":"Сергей","c":"Нижневартовск","d":"09.03.2019","t":"всем привет оставляю отзыв о чехлах на хонду фит 2005г кузов gd1 сшили чехлы просто отлично все отверстия которые есть в сиденьях подходят на 100 все изгибы и тд в подарок дали оплетку на руль под интерьер чехлов был выбор подушка или оплетка выбрал оплетку","car":"хонда фит"},{"b":"hyundai","f":"hyundai-creta","n":"Тоха","c":"Нижнесортымский","d":"01.03.2019","t":"Здравствуйте. Требовательно выбирал ателье по пошиву чехлов. Свой выбор пал на автостиль. Прочитал отзывы на разных сайтах и очень много было положительных отзывов. И решил заказать чехлы в автостиле. После заказа через сайт, оператор уточнила по телефону модель автомобиля, год производства и наличие и формы подголовников сидений. Это показало, что в фирме работают профессионалы своего дела. Обсудив все вопросы с оператором, Юлией которая советует и подсказывает какой цвет лучше выбрать и после этого окончательно сделал заказ. Свой выбор чехлов я не пожалел. Был поражён отличным качеством материалов и пошивом, который совпадал на 100% по всем элементам моего салона. Было учтено всё. Благодарен работникам фирмы. Когда натягивал, просто ориентировался на дырки сшили все \"по уму\" не докопаешься. Чехлы если все учесть и выполнить как по инструкции, то всё сядет как литое, без каких то либо нюансов. Обратил внимание на качество метериалов, поэтому выбранный мною чехлы из экокожи, приятно был удивлён качеством: экокожа мягкая, на ощуп и внешне, очень схожа с натуральной кожей. Правда не много расстроила доставка. Платная доставка осуществлялась долго. Чехлы были оплачены 16 января 2019 г., а получены 19 февраля 2019 г. Доставка оказывается в Сургутский район осуществляется по вторникам, вот это не оговаривается с оператором и ни где у них это не пишется. Установкой чехлов я занялся самостоятельно, предварительно проштудировав интернет. Передние и задние сели как влитые. Строчки задних сидений соответствуют заводским лекалам подголовников. А в целом я на данный момент доволен. Время покажет , надеюсь что эти чехлы мне прослужат долгое время. Удачи и успехов.","car":"Крета"},{"b":"suzuki","f":"suzuki-sx4","n":"Ольга","c":"Симферополь","d":"23.02.2019","t":"Выражаю благодарность работникам магазина!чехлы пошиты качественно и в указанные сроки.доставка очень быстрая.спасибо менеджеру за внимательное отношение.учли все нюансы при заказе.","car":"Сузуки sx4"},{"b":"honda","f":"honda-cr-v","n":"Татьяна","c":"Петропавловск - Камчатский","d":"20.02.2019","t":"Здравствуйте! Заказывала комплект чехлов на Honda CR-V, все пришло хорошо упаковано, качество замечательное. Рекомендую!!! Спасибо большое!!!","car":"CR-V"},{"b":"kia","f":"kia-ceed","n":"Валерий","c":"Тюменский р-н пос. Андреевский","d":"18.02.2019","t":"Заказ пришел очень быстро Заказываю уже второй раз Качеством очень доволен Спасибо Рекомендую ВСЕМ","car":"KIA CEED"},{"b":"mitsubishi","f":"mitsubishi-outlander","n":"Михаил","c":"ЕАО п.Теплоозерск","d":"14.02.2019","t":"Чехлы супер. Сшиты замечательно. Одеваются легко без всяких проблем. Спасибо большое.","car":"Аутлендер 3"},{"b":"uaz","f":"uaz-patriot","n":"Луиза","c":"Барнаул","d":"05.02.2019","t":"Сегодня получила авточехлы.Очень качественный пошив..Предусмотрено и выполнено всё о чём обговаривали с менеджером при заказе. Смотрятся чехлы на сиденьях замечательно.Приятно работать с такими ответственными и честными представителями Вашей компании.Всем рекомендую!!!","car":"УАЗ Патриот"},{"b":"nissan","f":"nissan-almera","n":"Руфат","c":"Челябинск","d":"23.01.2019","t":"Получил чехлы всё отлично я очень доволен","car":"Ниссан альмера"},{"b":"toyota","f":"toyota-auris","n":"Евгений","c":"Томск","d":"20.01.2019","t":"Заказал чехлы на свою Тойотку 21.12.18, Приехали в январе 19-го прямо на дом. Качеством пошива и материала очень доволен. Сели как родные. .Качество на высоте, все дырочки под подголовник на месте, чехлы сидят изумительно.Цена - качество на высоте. Рекомендую к сотрудничеству!!!","car":"Тойота Аурис"},{"b":"lada","f":"lada-niva-legend-4x4","n":"Юрий","c":"Волгоград","d":"18.12.2018","t":"Заказывал чехлы на передние сиденья 3.12.18. Получил заказ 17.12.18 . Отличный пошив !!! Рекомендую !!!","car":"ваз 21214 нива"},{"b":"nissan","f":"nissan-qashqai","n":"Виктор","c":"Петропавловск-Камчатский","d":"02.12.2018","t":"Получил свой заказ на ниссан кашкай (№ 11712), не первый раз заказываю на этом сайте подобную продукцию. Качество отличное, чехлы сели идеально. Были проблемы с доставкой (нарушен срок), представитель компании любезно предложил оплатить доставку самостоятельно. Работой и отношением данной компании удовлетворен. Спасибо.","car":"Ниссан Кашкай"},{"b":"mitsubishi","f":"mitsubishi-pajero-sport","n":"Алексей","c":"Нижнеангарск","d":"16.11.2018","t":"Доброго времени суток! Уважаемые покупатели, расписывать не буду. Скажу вкраци, чехлы просто ОГОНЬ!!! Спасибо ателье и менеджерам!!!","car":"Pajero Sport"},{"b":"toyota","f":"toyota-prius","n":"S.GAITSENREIDER","c":"с. Новосысоевка","d":"15.11.2018","t":"Привет Всем автомобилистам))) Отзыв КАТЕГОРИЧЕСКИ ФАЕР ПОЛОЖИТЕЛЬНЫЙ!!! ЧЕХЛЫ СТАЛИ КАК ЗАВОДСКИЕ. Оплетка руля тоже радует, увеличивает обхват не намного. Такие вещи берутся надолго, посему цена себя оправдывает однозначно. \n Еще раз отдельное спасибо Вам, девочки, за Ваши \"золотые\" руки и следовательно Наш комфорт)))\nВЫВОД: ВСЕМ БРАТЬ И ПРИЯТНОГО ПОЛЬЗОВАНИЯ","car":"TOYOTA PRIUS 30"},{"b":"lada","f":"lada-largus","n":"Наталья","c":"Воронеж","d":"13.11.2018","t":"Заказала чехлы в авто стил на ларгус. Довольна.","car":"Лада ларгус"},{"b":"toyota","f":"toyota-corolla-fielder","n":"Александр","d":"11.11.2018","t":"Получил чехлы , все подошло ! Огромное спасибо Светлане, хорошая консультация !","car":"Toyota fielder"},{"b":"lada","f":"lada-largus","n":"Сергей","c":"Краснодар","d":"05.11.2018","t":"Получил чехлы. Все прекрасно уже поставил доволен. Даже не ожидал .молодцы!","car":"Лада ларгус"},{"b":"toyota","f":"toyota-funcargo","n":"Заур","c":"Славянск-на-Кубани","d":"25.10.2018","t":"Всем доброго времени суток! Хочу оставить положительные эмоции по поводу чехлов на мое авто. Мне все понравилось, как оговаривалось так и сделали. Особенно как пошили. Идеально без лишних зазоров и все продумано под все эле элементы автомобиля. В общем очень доволен спасибо! Несколько фоток для наглядности.","car":"Toyota FunCargo","ph":["iblock/92b/IMG_20181010_104835.jpg","iblock/1b6/IMG_20181009_162531.jpg","iblock/655/IMG_20181009_162517.jpg"]},{"b":"toyota","f":"toyota-corolla-fielder","n":"Александр","c":"Якутск","d":"23.10.2018","t":"Всем доброго дня суток. Чехлы просто супер. Подошли в ровень. Внимание к каждым мелочам. Сшито качественно. Покупкой очень доволен. Спасибо.","car":"Toyota fielder 141g"},{"b":"nissan","f":"nissan-terrano","n":"Игорь","c":"Сыктывкар","d":"10.10.2018","t":"Отличные чехлы все подошло как влитое,спасибо большое,а самое главное все пришло очень бысто.","car":"Nissan Terrano"},{"b":"chevrolet","f":"chevrolet-niva","n":"Сергей","c":"Рубцовск Алтайский край","d":"27.09.2018","t":"Заказываю чехлы не в первый раз. Получил сегодня на Ниву. Все отлично. Сели как влитые. Одно жаль, сейчас на задних сиденьях идут фиксаторы для ремня безопасности, чтобы не болтался и не бил по двери. В чехлах нет прорези под эти фиксаторы, а самому резать не захотелось, только испорчу. Было бы замечательно этот момент учесть на будущее. Недавно продавал хундай, покупатель подумал что это с завода салон такой и сказал: \"Жалко сиденья, надо чехлы покупать\" Не верил что это чехлы из экокожи, так хорошо и плотно они сидели, за три года эксплуатации ни капли не износились. Рекомендую!!","car":"Нива Шевроле 18г.в.","ph":["iblock/d81/IMG-20180927-WA0001.jpeg","iblock/82d/IMG-20180927-WA0002.jpeg","iblock/3bd/IMG-20180927-WA0003.jpeg","iblock/e4b/IMG-20180927-WA0004.jpeg"]},{"b":"kia","f":"kia-rio","n":"Сергей","c":"Сочи","d":"21.09.2018","t":"Всё супер!\nБез лишних слов!\nСпасибо!\nЕдинственно ожидал доставку побыстрей до Сочи.","car":"Kia rio 4"},{"b":"toyota","f":"toyota-harrier","n":"Маргарита","c":"Тюмень","d":"18.09.2018","t":"Заказывала чехлы в июне 2017 года, сидят как влитые, качество супер. Чехлы комбинированные экокожа и алькантара в очень светлый салон. Заказ оформили быстро, пришли транспортной компанией вовремя (3 раб. дня) Большое спасибо Вам за вашу работу","car":"toyota Harrie"},{"b":"lada","f":"lada-largus","n":"Анатолий","c":"Йошкар-Ола","d":"16.09.2018","t":"Спасибо большое за чехлы. Все подошло отлично! Мололцы!","car":"Лада ларгус"},{"b":"toyota","f":"toyota-passo","n":"Евгений","c":"Владивосток","d":"08.09.2018","t":"ЧЕХЛЫ ОТЛИЧНОГО КАЧЕСТВА ,СЕЛИ ИДЕАЛЬНО.ДАЖЕ ОТВЕРСТИЯ ПОД ПОДГОЛОВНИКИ ПРОШИТЫ СТРОЧКОЙ.ДОСТАВКА ДО ВЛАДИВОСТОКА НЕ ДОЛГАЯ.ЕДИНСТВЕННЫЙ МИНУС ЭТО ТРАНСПОРТНАЯ КОМПАНИЯ DPD,НАХОДИТЬСЯ ДАЛЕКО.","car":"TOYOTA PASSO 2009 40/60"},{"b":"hyundai","f":"hyundai-porter","n":"Сергей","c":"Новосибирск","d":"29.08.2018","t":"Очень доволен чехлами!","car":"Hyundai Porter","ph":["iblock/73b/image.jpeg","iblock/cb3/image.jpeg"]},{"b":"toyota","f":"toyota-funcargo","n":"Артем","c":"Кемерово","d":"21.08.2018","t":"Заказал 14 апреля, получил 26. Отличные чехлы, сели как дома, ни чего подгонять и шить не пришлось.\nБольшое спасибо Юлии за грамотные консультации и хорошее настроение.\n И огромная благодарность девушкам в пошивочном цехе, спасибо, хорошая работа!\n Рекомендую!","car":"Тойота Фанкарго","ph":["iblock/88b/IMG_20180821_170457.jpg","iblock/3f1/IMG_20180821_170347.jpg","iblock/5d8/IMG_20180821_170332.jpg"]},{"b":"volkswagen","n":"Анатолий","c":"зима","d":"20.08.2018","t":"Заказ получил. Чехлы подошли Отлично. Девчонки спасибо вы молодцы.","car":"Фольцваген Туарег"},{"n":"Иван","c":"Новороссийск","d":"09.08.2018","t":"Качество супер, менеджер всегда на связи, все получил в установленный срок, все вырезы присутствуют, буду ставить ! Спасибо большое вашей команде, рекомендовал вас знакомым , жаль ,что ни на все марки bmw есть модели"},{"b":"tagaz","f":"tagaz-tager","n":"Роман","c":"Архангельск","d":"06.08.2018","t":"Друзья спасибо за чехлы! Я уже почти потерял надежду обновить салон своего почти раритетного авто. Предлагали много где поставить нечто универсальное. Не зря сопротивлялся. Обратившись к вам был приятно удивлен сервисом и вообще подходом к делу. Чехлы получил через транспортную компанию все в указанные сроки. Сели отлично! Поставил сам. Крепеж добротный и продуманный. Где надо липы где крючки где завязки. Салон преобразился. Спасибо еще раз за то чувство с которым теперь продолжаю кататься в полюбившемся мне автомобиле. Вы супер!","car":"Тагаз тагер 3д"},{"b":"audi","f":"audi-a6","n":"Анна","c":"Норильск","d":"31.07.2018","t":"Заказывали чехлы из экокожи в сентябре 2014, получили в срок. До сих пор отлично носятся, за исключением чехла на водительское кресло и то испортили сами. Фирма отшила все, как надо. Сели, как родные, всем советую.","car":"Ауди А6"},{"b":"hyundai","f":"hyundai-ix35","n":"Василий","c":"Калачинск","d":"15.07.2018","t":"Заказал пошиви авточехлов на хендай йх 35. Пришли все супер сели как на заводе. Спасибо большое!!!","car":"Ix 35"},{"b":"toyota","f":"toyota-premio","n":"Иван","c":"Комсомольск на Амуре","d":"08.07.2018","t":"Чехлы пришли вовремя, все подошло, смотрятся хорошо, заказывал с жаккардовыми вставками. Спасибо за качество, всего доброго.","car":"Toyota Premio"},{"b":"toyota","f":"toyota-corolla-fielder","n":"Анатолий","c":"Омск","d":"05.07.2018","t":"Спасибо за работу все подошло нормально ! доставка без проблем , рекомендую , не пожалеете !","car":"Toiota Filder"},{"b":"uaz","f":"uaz-patriot","n":"Ольга","c":"2010","d":"02.07.2018","t":"Получили чехлы для нашего Патриота. Просто великолепно, все подошло отлично, выглядят очень стильно. За подушку в подарок отдельное спасибо, очень нужная вещь оказалась ! Спасибо за отличную работу!","car":"УАЗ Патриот","ph":["iblock/6e6/IMG_20180630_230053.jpg"]},{"b":"mitsubishi","f":"mitsubishi-airtrek","n":"Виталий","c":"Томск","d":"18.06.2018","t":"Консультация , доставка на5 + ! Но когда я открыл посылку и стал рассматривать ?! Оператор меня консультировал что прорезать ничего не нужно! В итоге пришлось под подголовники на передние самому вырезать т.к нет даже прорезов , не то что прошитых отверстий как на задних ( там были) под подлокотник тоде нет ни замка чтобы всавить аккуратно ни прорези бональной ! Короче конструктор lego ! Материал сам хороший комплект полный ! Но поработать с ножом и ниткой придётся!!!","car":"Mitsubishi airtrek"},{"b":"subaru","f":"subaru-forester","n":"Надежда","c":"Южно-Сахалинск","d":"15.06.2018","t":"Спасибо огромное за чехлы! Заказывала мужу в подарок. Девушка менеджер несколько раз перезванивала для уточнения деталей (автомобиль японского производства). Менеджер предупредила, что могут быть несовпадения. Однако, чехлы сели идеально, хорошего качества! Рекомендую вашу фирму своим друзьям! Спасибо!","car":"Subaru Forester"},{"b":"honda","f":"honda-cr-v","n":"Эдуард","c":"Стерлитамак","d":"07.06.2018","t":"Благодарен работникам фирмы. Но есть некоторые просчеты в изготовлении чехлов и я надеюсь, что в дальнейшем эти минусы исключать в своей работе сотрудники фирмы и эта фирма не будет первой и последней по модельным авточехлам. Но все по порядку. После заказа через сайт, оператор уточнила по телефону модель автомобиля, год производства и наличие и формы подголовников сидений. Это показало, что в фирме работают профессионалы своего дела. Обсудив все вопросы с оператором, я также еще отправил фото по ватсапу сидений и самих подголовников и окончательно сделал заказ. Заказал из гладкой экокожи и алькантары черного цвета. Заказ прибыл вовремя согласно оговоренного времени. Установкой чехлов я занялся самостоятельно, предварительно проштудировав интернет. Передние сиденья я установил с подшивом сидений и спинки, т.к. без этого образуется из-за боковых поддержок эффект \"барабана\". Передние сели как влитые, но один минус на подушке сиденья отсутствует строчка на боковых поддержках из-за чего образуется складка, надеюсь в дальнейшей эксплуатации это не повлияет на долговечность чехлов (хотя что у нас вечное ?). Строчки задних сидений не соответствуют заводским лекалам, в связи с чем я не стал их подшивать, т.к. швы чехлов не совпадали с краями боковых поддержок и нижней части чехлов сиденья, из-за этого получился небольшой эффект барабана. Это второй минус. И еще одно огорчение, но небольшое которое исправимо- на спинках задних сидений отсутствовали прошитые отверстия под средний головник (хотя оператор уточняла про количество подголовников и это количество 5 штук мне и прислали), но эту ошибку я устранил, аккуратно прорезав отверстия и спрятав их под пластиковые направляющие подголовников. А в целом я на данный момент доволен. Время покажет , надеюсь что эти чехлы мне прослужат не менее трех лет. Надеюсь что в данной компании устранят незначительные ошибки по пошиву чехлов , приведя их к действительно заводским лекалам и на самом деле эта компания-фирма будет звучать \"Первый авточехол\" . Удачи и успехов. Также надеюсь, что мой отзыв не останется без внимания и может кому-то пригодится.","car":"Honda-CRV 2005","ph":["iblock/bde/чехлы переднего сиденья ,где отсутствует строчки на боковых поддержках по заводским лекалам и образуется складка..jpg","iblock/e53/чехлы 4.jpg","iblock/74d/чехлы 1.jpg","iblock/2d4/чехлы 3.jpg"]},{"b":"toyota","f":"toyota-ipsum","n":"Ольга","c":"Советская Гавань, Хабаровский край","d":"07.06.2018","t":"Заказали в середине февраля, получили 14 марта. Устанавливали сами, пришлось конечно повозиться, снимали все сиденья, установка заняла 3 часа. Результат супер! Единственный минус, чехлы на подголовники великоваты, но не критично ( на фото видно). Уже 2,5 месяца прошло после установки и всё отлично. Надеемся, что прослужат они не один год.","car":"Toyota Ipsum","ph":["iblock/8bd/IMG-20180426-WA0005.jpg","iblock/6a6/IMG-20180426-WA0009.jpg","iblock/e62/IMG-20180426-WA0006.jpg","iblock/a81/IMG-20180426-WA0008.jpg","iblock/8e3/IMG-20180426-WA0007.jpg"]},{"b":"gaz","n":"Анна","c":"Новосибирск","d":"24.05.2018","t":"Спасибо большое за чехлы. Очень понравились. Посмотрим, еак покажут себя в эксплуатации.","car":"Газель, тойота rav4","ph":["iblock/ce0/20180520_183243.jpg","iblock/c66/20180520_183318.jpg"]},{"b":"lada","f":"lada-granta","n":"Ян","c":"Санкт-Петербург","d":"16.05.2018","t":"Заказал 5-го мая, забрал 15-го. \nСиденья для установки не снимал, помогал друг. \nПо передним сиденьям притензий нету. \nНа задних не были прорезаны отверстия под подголовники что легко поправимо. Отверстия под держатели ремней безопасности на спинке были прорезаны неправильно.\nА так все сидит суперски, и выглядит \"дорохо-бохато\")","car":"Lada granta (norma)","ph":["iblock/475/IMG_20180516_071839.jpg","iblock/d54/IMG_20180516_071854.jpg"]},{"b":"skoda","f":"skoda-yeti","n":"Михаил","c":"Омск","d":"27.04.2018","t":"Хочу поблагодарить работников фирмы .большое вам спасибо.заказал чехлы пошили быстро .хорошее качество ,прекрасно сидят ,легко оделись .все прекрасно .за исключением брака ткани на одной детали.выслал фото ,написал.быстро ответили и пообещали прислать другую деталь .сегодня получил ее .большое вам человеческое спасибо.","car":"Шкода йети"},{"n":"Светлана","c":"Шилка","d":"20.04.2018","t":"4 апреля 2018г. сделала заказ на сайте Автостиль, чехлы из экокожи , для своего автомобиля toyota Ipsum , чехлы сшили, точь в точь на мой автомобиль, всё подошло по размеру, очень сильно пондравились, сшили качественно, быстро 14 апреля уже получили заказ. в подарок получили оплетку на руль. Спасибо вам большое!!! Очень довольны!!!!!!"},{"b":"renault","f":"renault-sandero-stepway","n":"Ирина","c":"Волгоград","d":"16.04.2018","t":"Заказала чехлы в ноябре 2017. Надела только сегодня. Поэтому отзыв запоздалый. Чехлы смотрятся обалденно. Экокожа черная с синими вставками. Единственное о чем пожалела, что заказала одну подушечку ( ну которая в подарок) сегодня ездили с дочкой, так друг у друга отбирали. Очень офигенная штука. Надо было две заказывать. Чехлы сели идеально. У кого машина как у менся, да еще с подушками безопасности в сиденьях, очень рекомендую. Так как ни у официального дилера, ни в фирменных магазинах рено такие чехлы купить невозможно. Даже на заказ. Их просто еще не шьют. Есть простые без прорезей под подушки. И отдельное спасибо менеджеру, уже не помню как зовут, но общаться было очень приятно. Цена более чем приемлимая. Чехлы упакованы были аккуратно . Принесли домой. Оценка за все пять с плюсом!!!!!","car":"Рено сандеро степвей"},{"b":"suzuki","f":"suzuki-liana","n":"Сергей","c":"Калуга","d":"09.04.2018","t":"Отличное качество.сели по размерам идеально.смотрятся красиво.по цене дешевле чем у конкурентов за такоеже качество.","car":"Suzuki Liana","ph":["iblock/c96/20180408_135415.jpg","iblock/b9f/20180408_135343.jpg"]},{"b":"hyundai","f":"hyundai-tucson","n":"Леонид","c":"Новосибирск","d":"29.03.2018","t":"29.03.18 забрал чехлы. Смотрятся хорошо,чуть-чуть не попали с цветом рогожки, но когда одел чехлы,то закрыл на это глаза. Подошли отлично, Большое Спасибо! Удачи Вам!","car":"Hyndai Tucson"},{"b":"suzuki","f":"suzuki-grand-vitara","n":"Николай","c":"Новосибирская область, г. Купино","d":"27.03.2018","t":"Чехлы пришли вообще просто шикарные. Подошли как влитые,2 беру чехлы по модели и ни разу не пожалел.смотрятся как кожаные сидения. Нигде ничего не подрезал,не делал дополнит. отверстий. Качество материала на 5+.Очень отзывчивый и доброжелательный персонал, все рассказали и подобрали по моим предпочтениям.Теперь буду заказывать только в этой фирме. Успехов и дальнейшего процветания Вам ребята!","car":"Suzuki Grand VITARA"},{"b":"toyota","f":"toyota-premio","n":"Евгений","c":"Тулун","d":"20.03.2018","t":"Чехлы садяться как родные, качество отличное, очень приятные скидки. доставили прямо к порогу, рекомендую поцаны! Буду всегда заказывать у вас чехлы, если будут действовать скидочки!","car":"Toyota Premio 240"},{"b":"toyota","f":"toyota-passo","n":"александр","c":"спасск-дальний","d":"20.03.2018","t":"не могу не высказать благодарность за ВАШЕ мастерство . Был приятно удивлен после установки чехлов. Все идеально. Предусмотрены все мелочи. Спасибо! Отдельное спасибо вашим телефонным операторам за терпимость и такт.","car":"тойота пассо"},{"b":"nissan","f":"nissan-terrano","n":"Vladimir","c":"Краснодар","d":"09.03.2018","t":"Отличные чехлы!Человеческое отношение!Фирма заботится о своей репутации.Отличная работа с клиентами!","car":"Nissan tirano"},{"b":"toyota","f":"toyota-verso","n":"Альберт","c":"Новотроицк","d":"25.02.2018","t":"Отвраительно! Не советую! Реклама не соответствует действительности. То с поколением автомобиля проблема, то с активными подголовниками. И в итоге заказ не приняли.","car":"TOYOTA VERSO"},{"b":"toyota","f":"toyota-corolla-fielder","n":"Сергей","c":"Омск","d":"23.02.2018","t":"Всем привет,пришли чехлы качество отличное.Задняя сидушка легла отлично,в спинках задних есть проблема для зацепа крючков т.к. там пластиковая защита и некуда зацепить крючки(одна металлическая планка,которая попадает под клипсу),в передней сидушке маловато одного шнурка(доработал резинками по бокам стало намного лучше) ,спинки передка нормально,но все чехлы не лежат по швам чуть свободны (кстати они не прошиты как на оригинале,нет поперечных строк поэтому нет нормального прилегания чехлов они под спиной подымаются(пишу не голословно до этого шила жена снимал каждое сиденье,подгоняли каждый шов,делали из ткани результат класс,просто цена на ткань возросла думал нет смысла париться) показал заказные одетые чехлы,сказали сшитые женой лучше полностью повторяют контур сиденья.В целом пойдет за такую цену не знаю сколько прослужат","car":"Toyota Fielder III"},{"b":"toyota","f":"toyota-land-cruiser-prado","n":"Денис","c":"Якутск,Якутия","d":"23.02.2018","t":"Чехлы просто огонь,сели идеально) рекомендую","car":"PRADO120","ph":["iblock/dd4/IMG_20180220_143145.jpg"]},{"b":"hyundai","f":"hyundai-solaris","n":"Андрей","c":"МО, Химки","d":"17.02.2018","t":"Почитал отзывы - подумал:\"Заказуха\". Но решил рискнуть, заказал - очень уж картинки красивые.\nЧтобы не парится заказал с установкой. Мастер натянул все за час.\nЧехлы шьются по марке АМ под конкретную модель, это большой плюс.\nРезюме:\nКачество чехлов, покрой отменные, чехлы сидят, как влитые.\nРекомендую всем!","car":"Huyndai Solaris 2017"},{"b":"honda","f":"honda-fit","n":"Юрий","c":"г.Иркутск","d":"15.02.2018","t":"Заказывал здесь чехлы, доволен всем: разговором с менеджером, четко, кратко и по существу; Сроками - когда обещали, тогда пошили и доставили. Качеством, чехлы подошли идеально. И маленький подарок , тоже +. Спасибо за хорошую работу, буду советовать обращаться в ваше ателье.","car":"Honda Fit"},{"b":"toyota","f":"toyota-prius","n":"Алексей","c":"Советская Гавань, Хабаровский край","d":"26.01.2018","t":"Заказывал чехлы из эко-кожи в конце декабря 2017 г. Курьер передал мне заказ 23 января 2018. Быстрое изготовление и доставка с учетом новогодних праздников. \nКачество пошива чехлов на 5 по 5-ти бальной системе. Установил чехлы совместно с помощницей в домашних условиях, так как у нас холодновато. Снимал все сиденья. Всё подошло практически идеально. Единственный недочет на задней правой спинке. Получилась небольшая гармошка по верхнему краю сиденья между отверстиями под подголовники. Но на фоне общего качества это мелочь. Огромное спасибо за дополнительный отрез материала для оклейки крышки бардачка между передними сиденьями. Эко-кожа прекрасно ведет себя во время натяжки по углам крышки. Перетянули примерно за 40 минут. Подарок - подушка получил тоже. Спасибо коллективу предприятия за Вашу работу. В скором времени закажу сыну на Тойоту Витс ко дню рождения. Держите марку \"Автостиля\". Удачи. Порекомендовал своим знакомым. Фото выложить не удалось.","car":"Тойота Приус 30"},{"n":"Николай","c":"Иркутск","d":"19.01.2018","t":"Перед новым годом заказал чехлы из эко кожи черные на фольцваген поло .\nПришли чуть раньше одевали точнее натягивали вдвоем около часа результат был просто великолепным машина хоть и новая но преобразилась, все подошло просто идеально . Люди которые отговаривали от чехлов и то согласились что салон стал горазда лучше .\nСпасибо !"},{"b":"toyota","f":"toyota-corolla","n":"Сергей","c":"Екатеринбург","d":"25.12.2017","t":"чехлы на свое авто заказывал с опаской но пришли вовремя и довольно не плохого качества подошло все как надо даже задний подлокотник в подарок была прислана оплетка на руль но как писали ранее в отзывах не подходит хочется сказать что если руки не от туда то и чехлы не подойдут у меня олетка была тоже великовата но после правильной прошивки на руле все село на место один минус нитки для прошивки ложат маловато а так все просто ок. спасибо.","car":"тойота королла"},{"b":"renault","f":"renault-megane","n":"Андрей","c":"Коломна","d":"22.12.2017","t":"Купил чехлы в этом магазине пару лет чехлы из жаккарда с \"красноой рогожкой\", отлично контрастировали с черным салоном, недавно продал машину, за 2,5 года не порвались и не рассыпались. Спасибо огромное. скоро опять закажу у вас для новой машины.","car":"Рено Меган 2 2007"},{"b":"toyota","f":"toyota-probox","n":"Александр","c":"Белокуриха","d":"22.12.2017","t":"Хочу сказать большое спасибо, за то что оперативно работаете, за то что помогли с выбором расцветки и очень быстро сшили и доставили, заказ сделал 9.12.18 пришел 19.12.18, объехал у нас все магазины в ближайших городах, не чего не нашел на мои не стандартные кресла. Всем советую заказывать здесь.","car":"Toyota Probox","ph":["iblock/685/20171222_184705[1].jpg","iblock/5cb/20171222_184720[1].jpg"]},{"b":"toyota","f":"toyota-corolla-spacio","n":"Олег","c":"Нязепетровск","d":"18.12.2017","t":"Сшили быстро. Отличная работа с клиентом, учтены все потребности. Качество исполнения на высшем уровне. Доставка до дверей. Лучшая цена. Все очень понравилось!","car":"Toyota corolla spasio"},{"b":"suzuki","f":"suzuki-grand-vitara","n":"Евгений","c":"Сургут","d":"18.12.2017","t":"Классные чехлы, качество на высоте!!!","car":"Сузуки гранд витара","ph":["iblock/e80/IMG_20171218_134753.jpg"]},{"b":"toyota","f":"toyota-rav4","n":"Ирина","c":"Сергиев Посад","d":"07.12.2017","t":"Хорошие авточехлы, качественная экокожа, мягкая, нет неприятного запаха, как у сомнительного качества экокожи. Сшито точно по лекалам автомобиля. Одели сами, без особых усилий. Нареканий нет. Покупкой довольна. Спасибо за качественно выполненную работу!","car":"Тойота Рав 4"},{"b":"toyota","f":"toyota-rav4","n":"Владимир","c":"Усть-Илимск","d":"05.12.2017","t":"Сделали очень быстро! Качественно! Но как обычно есть не большое \"но\",забыли сделать на задних сиденьях сзади прорези под крючки(кто знает,тот поймет) и еще не было обещанного подарка. Поставил сам,получилось очень красиво! Спасибо специалистам!","car":"RAV4-ll"},{"b":"hyundai","f":"hyundai-elantra","n":"Виктор","c":"Ангарск","d":"04.12.2017","t":"Заказал чехлы 19 ноября и уже 4 декабря курьер доставил. Нам с женой чехлы очень понравились. На сиденья одевали около часа, все подошло идеально. Большое спасибо менеджеру Светлане, все грамотно расспросила, всем рекомендую.","car":"Hyundai ELANTRA"},{"b":"toyota","f":"toyota-harrier","n":"Владимир","c":"Анадырь","d":"04.12.2017","t":"Заказал чехлы неуспел оплатить они уже готовы. Работают четко слаженно консультант постоянно на связи проблем никаких. Чехлы супер плюс подарок молодци спасибо большое.","car":"Харриер"},{"b":"skoda","f":"skoda-rapid","n":"Оксана","c":"КАЛИНИНГРАД","d":"22.11.2017","t":"Боялись заказывать по интернету, почитали комментарии, решились оформить заказ. Пошив действительно по нашей машине, все детали подошли идеально. Расцветка насыщенная, машина преобразилась. Один минус для нас в том, что хотели чехлы полностью из ткани, а такой заказ не изготавливают, из ткани сделали середину сидений. В общем все равно понравилось, остались довольны.","car":"Шкода Рапид"},{"b":"nissan","f":"nissan-x-trail","n":"Михаил","c":"Богучаны","d":"08.11.2017","t":"Молодцы ребята. Сделал заявку на обратный звонок, перезвонили, приняли заявку, при этом консультировали по всем вопросам (не фтюхивали, а советовали), оплатил 100% предоплаты + доставку до дома (опять советовали какая тк дешевли и быстрее довезет). И вот мои чехлы на авто. Подошли как родные, все нужные \"дырочки\" на нужном месте, швы ровные (подвальными \"швеями\" не пахнет). Я доволен, супруге нравиться, теперь детских ножек на сиденьях не боюсь.","car":"Икс трейл"},{"b":"mitsubishi","f":"mitsubishi-colt","n":"Дмитрий","c":"Петропавловск-Камчатский","d":"01.11.2017","t":"Все супер!!! Чехлы сели как надо , правда снимал салон так лучше одевать ,сидят так что и не видно что чехлы .Все отверстия прострочены . Заказывайте не пожелеете .","car":"Митсубиси Кольт"},{"b":"toyota","f":"toyota-prius","n":"Елена","c":"Лесозаводск","d":"31.10.2017","t":"8-го октября сделала заказ 30-го уже позвонил курьер. В наш регион (Приморский край) из Новосибирска - это просто супер быстро. Находилась на работе, курьер с удовольствием изменил адрес доставки. Чехлы очень понравились, продумано все до мельчайших подробностей. Даже не смотря что в каталоге нет праворукой модели и мы все обговаривали по телефону с менеджером. Менеджеру отдельное спасибо за понимание и терпение, т.к. у меня это первая машина и я не всегда понимала что у меня спрашивают. Был подарочек - оплетка на руль, но к сожалению на 4-5 см. великовата. Попробую из нее что нибудь перешить сама. Может накидку на бардачёк. Кстати этого то сильно и не хватает. Огромное спасибо Вашей команде за качество, удобство, обслуживание и сроки. Моя \"Красотуля\" стала еще уютнее.","car":"Toyota Prius 30"},{"b":"honda","f":"honda-cr-v","n":"Сургей","c":"Салаир","d":"20.10.2017","t":"Чехлы очень хорошие, поставил в течение часа. Есть небольшая недоработка. На задних чехлах нет прорези под ремни безопасности, пришлось прорезать ножом. Не прислали обещанный подарок оплетку на руль, зачем-то положили 4 лишних чехла на подголовники, лучше бы все-таки была оплетка. Но все равно спасибо, чехлы смотрятся солидно.","car":"HONDA CRV"},{"b":"lada","f":"lada-granta","n":"Алексей","c":"Красноярск","d":"17.10.2017","t":"Заказал чехлы из экокожи.изготовили и доставили довольно быстро,около десяти дней.приехал,оплатил и забрал заказ.насторожило то,что не прислали фото готовых чехлов,и когда забирал не было проверки товара,курьеры dpd там конвейер целый,подвозят,забирают,отдают,не до показзов.короче забрал и уехал.но когда открыл и начал установку чехлов, был очень удивлен и доволен качеством,все четко.так что рекоменду,а еще подушечку или оплетку на руль в подарок предлагают.остался доволен,спасибо большое.","car":"Lada granta liftbek"},{"b":"volkswagen","f":"volkswagen-polo","n":"Антон","c":"Санкт-Петербург","d":"05.10.2017","t":"Заказал Чехлы на поло седан , очень доволен покупкой. Хочу отдельно отметить клиентскую службу, все объяснили, рассказали, отправили. Светлана, Вы лучшая, спасибо за терпение. Получил чехлы дней через 20, кто то в комментариях грешил на курьерскую службу DPD, у меня проблем не возникло, курьер заранее не позвонил поэтому спокойно, терпеливо и лояльно ждал меня полчаса. Все чехлы точно в размер, установил за час самостоятельно, не имея прошлого опыта и навыков, единственное повозился с чехлами на подголовники, но эт не страшно ведь подушечка в подарок просто шик! Всем рекомендую!!!","car":"Polo"},{"b":"lada","f":"lada-vesta","n":"Леонид","c":"Новосибирск","d":"02.10.2017","t":"Чехлы супер, очень радуют. Установка проста","car":"Lada Vesta","ph":["iblock/06a/IMG_20170926_153222.jpg"]},{"b":"honda","f":"honda-fit","n":"Евгения","c":"Омск","d":"22.09.2017","t":"Спасибо огромное за чехлы!!все супер!я очень довольна!!","car":"Honda Fit 2002","ph":["iblock/737/IMG_0832.JPG","iblock/a98/IMG_0833.JPG","iblock/ccc/IMG_0831.JPG"]},{"b":"lada","f":"lada-niva-legend-4x4","n":"Артем","c":"Сочи","d":"19.09.2017","t":"Заказал чехлы на ниву пришли быстро. с установкой тоже не было ни каких проблем не снимая сидений заняло около 1 часа. сели как влитые такое чувство что их пошили у меня в машине)))) качество бомба вид супер )))) спасибо вам большое.","car":"Нива Урбан","ph":["iblock/6ca/ррр.jpg","iblock/69c/ллл.jpg"]},{"b":"nissan","f":"nissan-almera","n":"Валерий","c":"Барнаул","d":"17.09.2017","t":"Выбрал \"Автостиль\" из большого числа предложений и очень рад, что не ошибся: договор исполнен идеально, материал очень понравился, чехлы абсолютно точно облегают сиденья. Большое спасибо коллективу Автостиль, всем рекомендую. В порядке пожелания-отверстия в чехлах для фиксаторов подголовников увеличить на 1.5-2 мм - очень туго одеваются, можно порвать.","car":"ниссан альмера"},{"b":"toyota","f":"toyota-corolla-fielder","n":"Денис","c":"Петропавловск-Камчатский","d":"09.09.2017","t":"Здравствуйте,хочу сказать Вам огромнное спасибо за отличную выполненную работу. Установил чехлы,все как нужно,качество отличное,отшито супер,ни одной ниточки. Цена подарок. Спасибо.","car":"Тойота Филдер 2011г.выпуска"},{"b":"mazda","f":"mazda-mazda3","n":"Константин","c":"Новосибирск","d":"03.09.2017","t":"Неплохо, но качество не соответствует цене:\n- Не предусмотрена рукоятка регулировки поясничного упора водителя;\n- Не предусмотрены вырезы для укладки задних держателей ремней безопасности - есть только прорези.\n- Сзади чехол на спинке не повторяет форму сиденья - отсутствует необходимая прошивка, как на переднем, в результате чехлы неплотно прилегают.\nМенее выраженные недочёты тоже есть - на один из передних подголовников чехол подошёл идеально, на другой - не совсем. Местами прилегает недостаточно плотно.\nВ целом неплохо, рекомендую.","car":"Mazda 3","ph":["iblock/bc7/WhatsApp Image 2017-09-03 at 18.15.37.jpeg","iblock/08d/WhatsApp Image 2017-09-03 at 18.15.37(1).jpeg"]},{"b":"toyota","f":"toyota-rav4","n":"Наталья","c":"Сургут","d":"22.08.2017","t":"Доброго времени суток. Установила чехлы на автомобиль, качество отличное, отшито на совесть. Материал и цветовая гамма очень радуют. Год выпуска у меня 2006, поэтому немного есть нюансы, но это вообще не заметно и я думаю, что со временем все уляжется так как надо. Сами смотрите","car":"Toyota RAV4","ph":["iblock/f7d/20170819_111448.jpg","iblock/511/20170819_094538.jpg","iblock/c1c/20170819_111502.jpg","iblock/f05/20170822_143324.jpg"]},{"b":"renault","f":"renault-duster","n":"Елена","c":"Челябинск","d":"30.07.2017","t":"Два года прошло, как приобрела чехлы (март 2015). Через год сидение водителя стало выглядеть не очень ...","car":"Renault Duster","ph":["iblock/bda/2Ji6ApQFg-E.jpg","iblock/b40/oVQq2l74ZkE.jpg","iblock/956/v2f1xgvSkbg.jpg"]},{"b":"lada","f":"lada-vesta","n":"Виктор","c":"Новороссийск","d":"26.07.2017","t":"Спасибо за исполнение заказа,но...качество швов могло-бы быть и получше!!! А оплётку на руль(в подарок) ещё и нужно самостоятельно обшивать на руле...","car":"Vesta"},{"b":"toyota","f":"toyota-prius","n":"Ольга","c":"Уссурийск","d":"13.07.2017","t":"Чехлы отличные. Заказом очень довольны. Качество достойное. Всё подошло идеально. Спасибо!","car":"Toyota Prius 20"},{"b":"uaz","f":"uaz-patriot","n":"Николай","c":"Novosibirsk","d":"26.06.2017","t":"Всем доброго времени суток !\nЗаказал чехлы еще в марте месяце, в апреле уже были готовы , но не было времени их применить , и только 24 июня Я их поменял... \nпо факту....\nразмеры точно подходят по ширине спинки и сиденьям, \nесть одно но - на заднем сиденье есть куда руку положить- и туда чехол есть- я его одел и его можно между собой скрепить, но увы в конструкции моего автомобиля этого нет- и он пришит плотно- ну не беда так одел... \nтак же порадовало это боковое отверстие под ручку на переднем сидении\nО специалистах...\nОчень вежливое общение, легко подобрали мне цвет , и постоянно информировали меня о готовности моих чехлов ! за это отдельное спасибо !\nНу а теперь и ложка дегтя...( 27 июня... я запомню это печальное утро )\nпечально - но мой подарок пришел в негодность уже после первого одевания на руль ( \nочень разочарован - тот факт что я даже не принимал усилий , он лопнул... ( оплетка на руль ..... )","car":"Uaz patriot 2012","ph":["iblock/165/6HU8lqsBb8Y.jpg","iblock/564/cw0E0_pjGww.jpg","iblock/4f1/L8gvu4lmqR4.jpg","iblock/c71/6HU8lqsBb8Y.jpg"]},{"b":"toyota","f":"toyota-corolla-runx","n":"Александр","c":"Новокузнецк","d":"19.06.2017","t":"Спасибо,порадовали. Чехлы сшиты добротно,всё подошло,всё по размеру,всем советую данную фирму,есть ещё мастера на Руси.","car":"Тойота Ранкс"},{"b":"chevrolet","f":"chevrolet-lacetti","n":"Олег","c":"р.п. Чаны","d":"17.06.2017","t":"Купил, доволен, советую!","car":"Шероле Лачетти"},{"b":"toyota","f":"toyota-corolla","n":"Татьяна","c":"Пыть-Ях ХМАО-Югра","d":"17.06.2017","t":"«Добрый день! Наконец то муж одел чехлы на нашу Короллину... Сели очень хорошо, как влитые! В машине сразу стало очень стильно))). Спасибо огромное консультанту Светлане, очень приятное, располагающее и грамотное общение. Все в кратчайшее время обсудили, обговорили, оформили заказ. По электронке были пояснения на мои дополнительные вопросы (т.е. всегда есть обратная связь со специалистом), просто нет слов, каждое движение заказа оповещается по смс. Доставка в квартиру курьером, о чем еще остается мечтать... Замечательная Компания, прекрасный сервис и чудесное обслуживание! Спасибо!!!»","car":"Toyota Corolla E-150","ph":["iblock/96b/1497703158033_43.jpg","iblock/e04/1497703165157_44.jpg","iblock/f34/1497703169815_45.jpg","iblock/033/1497703175863_46.jpg","iblock/1a6/1497703180636_47.jpg","iblock/182/cZeuw9CPkAE.jpg","iblock/865/DQAZJFqo_jM.jpg","iblock/fd6/enna-q4LPPc.jpg","iblock/0c2/F6lVGmuNNKY.jpg","iblock/158/kCkLqo6LvDQ.jpg","iblock/864/KFrG11GxM6M.jpg"]},{"b":"nissan","f":"nissan-qashqai","n":"Владислав","c":"нОВОСИБИРСК","d":"04.06.2017","t":"Чехлы отличного качества. Сели как \"влитые\". Правда на заднем подлокотнике вырез не прямоугольный. И оплетка великовата в размере.","car":"Кашкай","ph":["iblock/c6b/20170603_173250.jpg","iblock/b51/20170603_173018.jpg"]},{"b":"toyota","f":"toyota-funcargo","n":"Николай","c":"Санкт-Петербург","d":"31.05.2017","t":"Хочу выразить признательность и благодарность специалистам фирмы Автостиль за оперативный пошив и отправку чехлов на мою машинку. С новыми чехлами автомобиль выглядит как игрушка и нравится не только мне, но им всем кто хоть раз посидел на стильных и красивых чехлах выполненных в Автостиле.","car":"Toyota Funcargo"},{"b":"toyota","f":"toyota-probox","n":"Сергей","c":"Хабаровск","d":"27.05.2017","t":"Пришли чехлы, качество отличное, поставили вдвоем за час! Салон стал смотреться шикарно )","car":"Toyota probox","ph":["iblock/346/9aeea847-1eec-40ab-93af-c875a0b26363.jpg","iblock/17c/fd7eb877-dc46-40bb-b493-7b4450754285.jpg"]},{"b":"toyota","f":"toyota-prius","n":"Александр","c":"Нерюнгри","d":"18.05.2017","t":"Добрый день!я хотел бы поблагодарить компанию\"АВТОСТИЛЬ\"! За добросовестный труд и качество продукции! Заказал чехлы на приус2 очень понравились и сидят как родные. И отдельная благодарность диспетчерам!Очень внимательные и вежливые! Буду рекомендовать Вашу компанию! Большое спасибо!","car":"Тойота приус 2"},{"b":"nissan","f":"nissan-juke","n":"Ирина","c":"Иркутск","d":"16.05.2017","t":"Спасибо большое за оперативность и сервис! Всё доброжелательно и быстро. Чехлы отличные! Спасибо большое !!!","car":"Nissan Juke"},{"b":"suzuki","f":"suzuki-jimny","n":"Яна","c":"Рязань","d":"15.05.2017","t":"Хочу выразить благодарность менеджеру Юлии, которая принимала заявку и вела мой заказ. Очень приятная и терпеливая девушка, учла все мои пожелания и ответила на все мои бесконечные вопросы. Также хочется поблагодарить тех, кто именно шил чехлы.\nО плюсах: \n- материал выглядит достойно (посмотрим как он покажет себя через некоторое время)\n- качественная строчка, нигде не торчат нитки, швы аккуратные, края заделаны\n- чехлы сели как влитые на сидения...\nЕдинственное, чего бы я хотела еще от этих чехлов, чтобы на заднем сидении была выемка для замков ремней безопасности, как в оригинальных сидениях, теперь замки просто торчат вверх, их вниз в сидение уже не спрятать((( Может это чисто технический момент....\nЖелаю процветания вашей фирме. Спасибо за качественный товар!!! Всем друзьям уже вас порекомендовала.","car":"Suzuki Jimny","ph":["iblock/617/Cdss0QWBp78.jpg","iblock/d3d/cmf_0DtJN7c.jpg","iblock/0ef/GjbUlTulD2E.jpg","iblock/a67/RJ11veDnHzk.jpg","iblock/745/8HO0Fx83Lt0.jpg"]},{"b":"mitsubishi","f":"mitsubishi-l200","n":"Газиз","c":"Баймак","d":"14.05.2017","t":"Чехлы подошли отлично. Качество пошивки хорошее, по размерам совпало без нареканий. Порадовало то, что в комплекте даже на подлокотник есть чехол. Спасибо!","car":"Mitsubishi L200"},{"b":"nissan","f":"nissan-dualis","n":"Павел","c":"Комсомольск- на-Амуре","d":"09.05.2017","t":"Чехлы очень понравились, подошли как родные, всем рекомендую данную компанию. Желаю процветания и дальнейших успехов ООО автостиль г. Новосибирск","car":"Ниссан дуалис"},{"b":"toyota","f":"toyota-premio","n":"Павел","c":"Омск","d":"03.05.2017","t":"Хочу выразить благодарность за качественную продукцию, хорошую обратную связь, адекватную ценовую политику, ну и подарочную подушку. Все оделось идеально и без складок. Из выявленных недостатков хотелось бы отметить то, что забыли прошить отверстие под кронштейе крепления полки (скобу). Всего их 4 шт., а отверстий под них оказалось 3. Очень полезная вкладка на сайте с инструкцией по монтажу чехлов. Без данной информации можно допустить массу ошибок. Так же в комплекте идет материал для самостоятельной перетяжки подлокотника. Конечно хотелось бы, чтобы это было готовое изделие,так как очень легко ошибиться, делая самому, а отдавать кому-то - это дополнительные финансовые затраты. Итогом очень доволен, надеюсь прослужат не один год.","car":"Toyota Premio (T240)","ph":["iblock/b27/243d2b1s-960.jpg","iblock/08a/43d2b1s-960.jpg","iblock/ea2/43d2b1s-960.jpg","iblock/8f7/370a5b1s-960.jpg","iblock/38b/8a5b1s-960.jpg"]},{"b":"hyundai","f":"hyundai-getz","n":"Валерий","c":"Собинский р-н п Ставрово","d":"29.04.2017","t":"Сегодня надел чехлы,все подошло хорошо .Качество отличное.Мне понравилось.Большое спасибо.","car":"Hyundai Getz","ph":["iblock/4b1/CAM00193.jpg","iblock/996/CAM00191.jpg","iblock/78c/CAM00197.jpg","iblock/74d/CAM00198.jpg"]},{"b":"lada","f":"lada-granta","n":"Людмила","c":"Киров","d":"26.04.2017","t":"В конце декабря заказывала чехлы, пришли вовремя, но вот сейчас стали их одевать, а дырки у задних подголовников не подходят, пришлось переделывать самим, потому что расстояние дырок только для маленьких подголовников.","car":"Лада гранта (Норма)"},{"b":"nissan","f":"nissan-almera","n":"Андрей","c":"Барнаул","d":"23.04.2017","t":"Добрый день! Заказывал чехлы из экокожи с вставкой жаккарда. В феврале получил.\nПролежали они до вчерашнего дня)\nУстановил в машину, получилось красиво.\nНО!!!\nПочему-то на передние сидения сделали неправильно... Как для праворульной машины.\nПотому что регулировка водителя получилась под чехлом, а у пассажира наоборот (на фото видно)\nНе видел праворульных Альмер N16...","car":"Nissan Almera N16","ph":["iblock/d4b/IMG_20170422_182112.jpg","iblock/d38/IMG_20170422_182130.jpg","iblock/018/IMG_20170422_203134.jpg","iblock/e1a/IMG_20170422_203212.jpg"]},{"b":"lada","f":"lada-vesta","n":"Тимков Сергей","c":"Красноярск","d":"21.04.2017","t":"Большое спасибо! Чехлы просто супер!","car":"LADA  Vesta"},{"b":"lada","n":"Михаил","c":"Белгород","d":"16.04.2017","t":"Здравствуйте! Заказывал у вас чехлы, изготовлено было все в оговоренные сроки и все хорошо подошло. Цена чехлов тоже приемлемая. Рекомендую знакомым тоже заказать у Вас чехлы на машину. Спасибо за своевременное смс оповещения и действительно качественный товар!!!","car":"ваз 2114"},{"b":"uaz","f":"uaz-patriot","n":"Владислав","c":"Хабаровск","d":"11.04.2017","t":"Все приехало! Все поставлено! Всем нравится! Заказываю сыну! Спасибо за качественную работу!","car":"УАЗ Пикап","ph":["iblock/003/20170409_152908.jpg","iblock/1cc/20170409_152856.jpg"]},{"b":"toyota","f":"toyota-rav4","n":"кирилл","c":"г.Шилка","d":"09.04.2017","t":"чехлы супер, указал модель авто и год выпуска, сшиты по размерам ни миллиметра больше ни меньше, всем советую, авто преобразилось, салон выглядет солидно, спасибо!!!","car":"toyota rav-4  2006 года"},{"b":"hyundai","f":"hyundai-santa-fe","n":"Игорь","c":"Екатеринбург","d":"07.04.2017","t":"Чехлы на 4 с минусом. Все чехлы сели хорошо но вот заднее сидение спинка пошита с браком липучка не достаёт другой, в целом не заметно но когда раскладываешь спинку сидения чехол болтается как тряпка. Чехол пошитый на бокс (вещевой подлокотник)почему-то с острыми углами и они торчат. Если присмотрется то выглядит смешно. Фото скину позже. Брал чехлы поздней осенью 2 года назад,а поставил в мае поэтому не стал высказывать претензию, пишу чтобы в дальнейшем не допускали таких ошибок,если хорошая компания то я думаю при слушается к отзыву.","car":"Хендай Санта Фе 2"},{"b":"honda","f":"honda-fit","n":"Юлия","c":"Большой Камень. Приморский край","d":"26.03.2017","t":"В общем чехлами довольна как удав","car":"Honda Fit","ph":["iblock/333/IMG_2476.JPG","iblock/dd4/IMG_2477.JPG"]},{"b":"toyota","f":"toyota-funcargo","n":"Ирина","c":"Екатеринбург","d":"19.03.2017","t":"Здравствуйте.Не могу не оставить свой отзыв о работе этой компании.В первых числах марта занялась поиском авточехлов на нашего красавчика Фунтика,и это оказалось не так просто,оказалось что на мальчишку сложно найти кто отшивает,после длительных поисков писем на почту,мне ответили,ответили девчонки из Новосибирска после того как мы детально все обсудили по модели,спустя несколько дней обдумывания,все таки интернет магазин и без замеров шьют чехлы,но почитав отзывы я В приняли решение,сделали предоплату 1т и еще раз поговорив со Светланой менеджеру оформили заказ.Мы не разочаровались,заказ пришел очень быстро,17марта мы уже забрали наряд для мальчишки.Сегодня 18 марта,муж обновил салон.И спешу поблагодарить девчонок за оперативную и качественную работу.Все довольны,размечик Фунтику подошел,все аккуратно и качественно.Рекомендую","car":"Тойота Функарго","ph":["iblock/ddd/14899286781121118263705.jpg"]},{"b":"mazda","f":"mazda-cx-5","n":"Павел","c":"Мирный","d":"14.03.2017","t":"Добрый день! Вчера установил чехлы. Проблем не возникло. Еще раз большое спасибо!","car":"Mazda CX-5","ph":["iblock/fd2/DSC_0351.JPG","iblock/727/DSC_0352.JPG"]},{"b":"toyota","f":"toyota-funcargo","n":"Александр","c":"Заречный","d":"12.03.2017","t":"Нашел ваш сайт в интернете, заказал, получил товар в срок. При осмотре, на качество пошива и материала, остался доволен. Спасибо!","car":"Toyota  Fun Cargo","ph":["iblock/d8e/2017-03-12 17-21-16.JPG","iblock/178/2017-03-12 17-20-47.JPG","iblock/869/2017-03-12 17-21-36.JPG","iblock/7b3/2017-03-12 17-22-13.JPG"]},{"b":"nissan","f":"nissan-terrano","n":"Андрей Меньшиков","c":"Пермь","d":"06.03.2017","t":"Чехлы пошиты очень качественно, доставлены в срок.\nБольшое спасибо за вашу работу.","car":"Nissan Terrano"},{"b":"toyota","f":"toyota-land-cruiser-prado","n":"Светлана","c":"Находка","d":"04.03.2017","t":"Добрый день. На 23 февраля заказала чехлы в подарок мужу на Ленд Крузер Прадо. Вчера получила.Мужу очень понравились, большое спасибо. Но я немного расстроилась, заказывала с окантовкой и оплатила с учетом ее. Все хорошо, но немного остался осадок.","car":"Прадо"},{"b":"renault","f":"renault-megane","n":"Константин","c":"Ялта","d":"02.03.2017","t":"Качество пошива - 5\nСоответствие размерам - 5\nКачество крепежа резинок и липучек - 3. Несколько штук оторвалось при монтаже.\nКлиентоориентированность - 5\nУстановка не сложная.\nВид посвежевшего салона - бесценно.\nБуду рекомендовать.","car":"Renault Megane 3"},{"b":"mitsubishi","f":"mitsubishi-lancer","n":"Екатерина","c":"Московская область, г. Люберцы","d":"28.02.2017","t":"Чехлы хорошо подошли под цвет автомобиля. Хорошее качество. Вежливые менеджеры по продажам. Юлии отдельно спасибо. Рекомендую заказывайте не пожалеете.","car":"Mitsubishi Lancer 9"},{"b":"honda","f":"honda-cr-v","n":"Cветлана","c":"Междуреченск","d":"19.02.2017","t":"Заказала чехлы, пришли быстро. Сделано качественно, очень понравились огромное спасибо вам, буду рекомендовать друзьям!!!","car":"Хонда СРВ","ph":["iblock/a1f/20170218_191020.jpg","iblock/555/20170218_201735.jpg"]},{"b":"honda","f":"honda-stepwgn","n":"ВИТАЛИЙ","c":"КРАСНОЯРСКИЙ КРАЙ","d":"17.02.2017","t":"Спасибо за чехлы,классная работа от а до я.От заказа до доставки.","car":"HONDA STEPWGN"},{"b":"nissan","f":"nissan-x-trail","n":"Игорь","c":"Комсомольск-на-Амуре","d":"15.02.2017","t":"СПАСИБО !!! ЮЛЯ всё подошло с Вами приятно иметь дело !!! Буду заказывать для друзей они с нэтом не дружат но всем понравилось. Процветания Вашему бизнесу !!! \nМожно разместить в отзывах, а фото на сайте.","car":"Nissan X-trail T31 (правый руль)","ph":["iblock/b25/хтреил првый 31 (2).jpg","iblock/59c/хтреил првый 31 (3).jpg","iblock/84f/хтреил првый 31.jpg"]},{"n":"Николай","c":"Симферополь","d":"14.02.2017","t":"Добрый день! Получил чехлы. Качество хорошее!\nЕще не ставил. Но вот с подарком (оплётка на руль) не вышло!! Больше часа шил.... во первый шнур короткий, только на половину! Так еще и размер не подошел!! В конце получилась складка (чехол значительно больше руля) вроде как и подарок. Но жалко потраченное время!","ph":["iblock/76c/20170214_102750.jpg","iblock/1f8/20170214_102742.jpg"]},{"b":"honda","f":"honda-fit","n":"Евгений","c":"Новокузнецк","d":"05.02.2017","t":"Огромное спасибо вам, нам с женой все понравилось.","car":"Honda fit ge6","ph":["iblock/b2a/DSC_0408-min.JPG","iblock/2f6/DSC_0408-min.JPG"]},{"b":"daewoo","f":"daewoo-gentra","n":"Николай","c":"Астраханская область","d":"24.01.2017","t":"Спасибо,чехлы понравились,заказ был выполнен в срок и с хорошим качеством！","car":"Джентра"},{"b":"lada","f":"lada-priora-vaz-2110","n":"Магомед","c":"Чеченская республика,шелковой район ст.курдюковская","d":"12.01.2017","t":"Хочу чехлы по бокам черные а по середине белые в полосочку как на фото я видел.","car":"Приора"},{"b":"toyota","f":"toyota-passo","n":"Елена","c":"Челябинск","d":"12.12.2016","t":"Хотелось бы отметить очень хорошее качество!\nЧехлы красивые, сели на кресла идеально, что не может не радовать! \nЕдинственное замечание: отсутствие оработанного отверстия для крепления подлокотника. Пришлось вырезать самостоятельно, что, впрочем, неплохо получилось.\nСпасибо за приятное сотрудничество и быстрые сроки изготовления!","car":"Toyota Passo"},{"b":"honda","f":"honda-fit","n":"Ольга","c":"Дальнегорск","d":"04.12.2016","t":"Чехлы одели за два часа, сели как влитые .Очень довольны. Заказали еще и родителям..","car":"Honda-Fit"},{"b":"honda","f":"honda-cr-v","n":"Валерий Киреев","c":"п. Кшенский","d":"03.12.2016","t":"Доброго времени суток! Спасибо огромное, за качество и оперативность доставки. Буду рекомендовать всем знакомым. Еще раз спасибо!","car":"Honda CRV-2"},{"b":"renault","f":"renault-duster","n":"Кирилл","c":"Ростов-на- Дону","d":"02.12.2016","t":"Спасибо за качество !!! Когда заказывал боялся, получил чехлы быстро, без проблем, Спасибо огромное ! Планирую жене заказать на Митсубиси Поджеро","car":"Рено Дастер"},{"b":"fiat","f":"fiat-ducato","n":"Юрий","c":"Ростов-на-Дону","d":"20.11.2016","t":"Покупал чехлы год назад , выглядят как новые до сих пор. Спасибо за качество.","car":"Фиат Дукато"},{"b":"kia","n":"Валерий","c":"Ефремов","d":"14.11.2016","t":"Всем привет.А у меня дырки под подголовники не совпадают.А если их тянуть то другии не совпадут либо весь перекосится","car":"киа спортриж","ph":["iblock/244/IMG_20161111_104649.jpg"]},{"b":"toyota","f":"toyota-harrier","n":"Вера","c":"пенза","d":"06.11.2016","t":"Здравстуйте!!!! Благодарны за чехлы из экокожи! Подошли идеально,очень красивые. УДАЧИ ВАМ И БЛАГОДАРНЫХ КЛИЕНТОВ!","car":"ТАЙОТА ХАРИЕР"},{"b":"toyota","f":"toyota-corolla-fielder","n":"Виктор","c":"Саянск","d":"26.10.2016","t":"Здравствуйте, Вашей компанией Очень доволен. Все пошито очень качественно и в короткие сроки. Оплатил 10.10.2016 и доставили прямо до двери 25.10.2016. Чехлы оделись как влитые без складок, швы очень качественные. Салон автомобиля значительно преобразился. Всем советую здесь делать заказ. Спасибо вам огромное за ваш труд.","car":"Toyota Corolla Fielder"},{"b":"mitsubishi","f":"mitsubishi-airtrek","n":"Юрий","c":"Холмск","d":"20.10.2016","t":"Отлично !!!Большое вам спасибо , как влитые.","car":"Митсубиси аиртрек"},{"b":"uaz","f":"uaz-patriot","n":"лариса","c":"ПОЙКОВСКИЙ ХМАО-ЮГРА","d":"09.10.2016","t":"Доброго времени суток!Чехлы подошли,сели как влитые. Пошив качественный, спасибо за подарок.","car":"UAZ PATRIOT LIMITED"},{"b":"toyota","f":"toyota-land-cruiser-prado","n":"Алексей","c":"Барнаул","d":"01.10.2016","t":"Качественно сшиты, отлично сидят. Вообщем рекомендую , отличные чехлы.","car":"TLC Prado"},{"b":"toyota","f":"toyota-prius","n":"Марина","c":"Уссурийск","d":"24.09.2016","t":"Добрый день. Вчера одели чехлы, очень довольны. Красота да и только. Всем буду советовать ваш сайт.","car":"Приус"},{"b":"renault","f":"renault-duster","n":"Легостаева Ольга Викторовна","c":"г.Тюмень","d":"15.09.2016","t":"Хочу сказать большое спасибо. Очень боялась что не подойдет. Подошло идеально. Все устроило. Сшито аккуратно. Быстро доставили. Молодцы.","car":"Рено Дастер 2016"},{"b":"kia","f":"kia-cerato","n":"Людмила","c":"Сыктывкар","d":"12.09.2016","t":"Доброго времени суток! Получили чехлы, причем очень быстро! Сразу установили, одевали их прямо в машине, снимали только заднюю сидушку, получилось очень хорошо. Ещё раз спасибо!","car":"Kia Cerato new","ph":["iblock/8df/IMG_20160908_171532.jpg","iblock/28f/IMG_20160910_171916.jpg","iblock/05d/IMG_20160910_171907.jpg","iblock/aed/IMG_20160910_171931.jpg","iblock/72b/IMG_20160908_171403.jpg"]},{"b":"suzuki","f":"suzuki-vitara","n":"Игорь","c":"Прохладный","d":"23.08.2016","t":"Здравствуйте. Чехлами остался очень доволен, шьют по заводским лекалам, настоящие профессионалы своего дела. Заказывал из рогожки + экокожа. Огромное спасибо менеджеру Юли за помощь в выборе. Кто хочет брать берите даже не сомневайтесь, останетесь довольны. Установил сам, седения не снимал, оделись как родные, кто не знает даже не догадается что это чехлы. Ещё раз большое спасибо.","car":"Suzuki Vitara 2016","ph":["iblock/19a/P_20160823_080926_1_p.jpg","iblock/866/P_20160823_080905_1_p.jpg","iblock/c1f/P_20160823_080940_1_p.jpg","iblock/ec8/P_20160823_080851_1_p.jpg"]},{"b":"ford","f":"ford-c-max","n":"Олег Панов","c":"Коломна","d":"21.12.2015","t":"Почти полгода как установил чехлы из эко кожи.... и решил сделать отзыв. Почему через полгода? Да потому что кроме первых очень приятных впечатлений от обновленного салона (выглядит добротно, хоть и сам надевал чехлы), могу теперь добавить, что и через полгода придраться не к чему. Чехлы приняли форму окончательно, и их мои знакомые считают как установленные заводом.... Я не тороплюсь переубеждать..))) Соотношение цена/качество очень привлекательно.... И \"выносил мозг\" менеджерам оказалось зря. Благодарю менеджера Надежду Иванову за терпение и обстоятельность общения!!!! С наступающим Новым годом!!!!","car":"Ford C-max"},{"b":"ford","f":"ford-c-max","n":"Артур","c":"Тюмень","d":"27.11.2015","t":"Авточехлы отличного качества, сели как литые.Оформление заказа, доставка и соправождение заказа на высшем уровне.Огромное спасибо!!!","car":"FORD C-MAX"},{"b":"opel","f":"opel-corsa","n":"Нина","c":"Москва","d":"21.11.2015","t":"Всем доброго дня! Очень хочется поделиться своим впечатлением о работе компании АВТОСТИЛЬ! \nНашла компанию в и-те. Не смотря на разницу во времени, все вопросы по заказу решались четко и профессионально (у меня первая машина и нет опыта-помогли правильно подобрать комплект под марку!) Учли мои капризы по поводу контрастной отстрочки-ПОЛУЧИЛОСЬ ОЧЕНЬ КРУТО! Заранее пришло смс о том что заказ готов ,отправляется. Получила точно в срок ,через DPD.Установкой занимался мастер в Москве(могу дать номер).Сделал с подшивкой и оценил качество чехлов как очень высокое! В общем, всем рекомендую! Чехлы сшиты так ,что когда их одели да ещё с подшивкой к сиденьям-ОЩУЩЕНИЕ НОВОГО ЗАВОДСКОГО КОЖАННОГО САЛОНА! Ребята спасибо за Вашу профессиональную работу! Лекала СУПЕР!!!! я ни секунды не пожалела ,что обратилась именно к Вам! Даю свою почту ,если нужно фото пришлю! Заказ Opel Сorca 3-х двер. черный с синей контрастной нитью.! СПАСИБО ВАМ!!!","car":"Opel Corca"},{"b":"great-wall","f":"great-wall-hover-h5","n":"Александр","c":"Омск","d":"16.11.2015","t":"Заказывал чехлы из эко кожи на Ховер Н5. Пришли вовремя, красивые, прочные, качественно сшиты, все на высшем уровне, одни положительные эмоции. Всем рекомендую, не пожалеете. Принимавшим участие в оформлении, изготовлении и отправке моего заказа большое спасибо за работу. Желаю дальнейших успехов. Удачи. С уважением А. Шевцов.","car":"Ховер H-5"},{"b":"mazda","f":"mazda-mazda6","n":"Анатолий","c":"Иваново","d":"14.11.2015","t":"Скажу коротко: сервис отличный,чехлы супер , все как надо село. Я не пожалел что заказал.Молодцы так держать.","car":"MAZDA 6"},{"b":"volkswagen","f":"volkswagen-jetta","n":"Елена","c":"Ачинск","d":"10.11.2015","t":"Здравствуйте! Спасибо за прекрасное обслуживание, быструю и удобную доставку, а главное за прекрасное качество авточехлов.Красота! Все подошло очень хорошо, кроме чехла на подлокотник, справа от водителя, он совсем далек от размера, не подходит сантиметра на 3-4. Машина, как новая! Советую всем! Еще раз СПАСИБО!!!","car":"фольксваген  \"Джетта\""},{"b":"uaz","f":"uaz-patriot","n":"Надежда","c":"Челябинск","d":"08.11.2015","t":"Огромное спасибо всем за работу. Чехлы получили к сроку, в который я просила уложиться. Качество отличное. Правда, надеть еще не успели - позже обязательно об этом напишу. Отдельная благодарность за понимание менеджеру Елене. И компания DPD отработала четко. Молодцы. Удачи всем и во всем!","car":"УАЗ-Патриот"},{"b":"kia","f":"kia-sportage","n":"Екатерина","c":"Давлетшина","d":"28.10.2015","t":"Огромное Вам спасибо!!!! чехлы просто супер.Качество превосходное,оделись отлично без затруднений,а сидят как влитые. Доставка прям к дому. Советую своим знакомым,так что ждите заказов!!!!! Спасибо.","car":"Kia Sportage III"},{"b":"hyundai","f":"hyundai-tucson","n":"Анатолий","c":"Сургут ХМАО","d":"17.10.2015","t":"Доброго дня! Чехлы установил, сели как родные, проблем не возникло. Салон смотрится дорого. В уходе очень практичны, у нас маленький ребенок, то что-то прольет-просыпет, то в грязной обуви по салону лазит, достаточно влажной салфеткой протереть и чехол как новый. Очень довольны! Заказ был выполнен в кратчайшие сроки. И еще подарок был на скидку на следующий заказ, можно сделать хороший подарок друзьям. Большое спасибо! Мы очень довольны.","car":"Хундай Туксон"},{"n":"Юрий","c":"Ломоносов","d":"29.07.2015","t":"Получил заказ,Качеством доволен.Большое спасибо.","car":"Актион"},{"b":"toyota","n":"Сергей Косяков","c":"Омск","d":"28.07.2015","t":"Купили авточехлы, наконец-то нашли время их надеть. Смотрится отлично! Спасибо \"АВТОСТИЛЮ\"","car":"Toyota","ph":["iblock/0a9/111.jpg","iblock/214/222.jpg","iblock/427/333.jpg"]},{"b":"opel","f":"opel-mokka","n":"Анна Ткаченко","c":"Мирный (Якутия)","d":"22.07.2015","t":"Добрый день! Наконец то и мы получили чехлы на нашу машинку... Сели хорошо в машине сразу так светло стало))). Но есть и косяки: первое это то что на задней спинке забыли сделать дырки для среднего подголовника, второе это то, что на задних седушках нет крючков для крепления только шнурок, поэтому они не идеально обтягивают седение! А так все очень даже ничего... Спасибо!!!","car":"опель Мокка"},{"b":"opel","f":"opel-corsa","n":"Михаил Дроздов","c":"Екатеринбург","d":"07.07.2015","t":"Чехлы получил. Все получилось отлично, огромное Вам спасибо. Отдельную благодарность хотелось бы выразить немецким конструкторам автомобиля OPEL CORSA, энное количество лестных слов прозвучало в их адрес в момент установки чехлов","car":"OPEL CORSA","ph":["iblock/6e8/DSC_0006.JPG","iblock/2d0/DSC_0007 (1).JPG"]},{"b":"ford","f":"ford-fusion","n":"Евгений","c":"нсо г.Куйбышев","d":"01.07.2015","t":"Остался доволен,чехлы подошли замечательно! Салон стал как новый.Света,Олеся Вам отдельное спасибо!","car":"форд фьюжен","ph":["iblock/82e/IMG_5840.JPG","iblock/b65/IMG_5841.JPG"]},{"b":"mazda","f":"mazda-mazda6","n":"Георгий","c":"Новокузнецк","d":"30.06.2015","t":"Отличные чехлы для сидений моей mazda 6.\nБольше всего понравилось само качество чехлов, прошло уже 3 месяца, езжу часто, езжу не один, а форму они не потеряли, брал эко-кожу","car":"mazda 6"},{"b":"suzuki","f":"suzuki-jimny","n":"Валерий Николаевич","c":"Оренбург","d":"19.06.2015","t":"Чехлы на Сузуки Джимни получил, передние сиденья уже одел. Пребываю в безумной радости, никогда в жизни в этой стране не видел такого качественного исполнения работы. Просто супер, кто-то их делал явно с душой, точность и аккуратность просто превосходная. Я - эндохирург, для меня миллиметр большая величина и обычно я вижу все огрехи. Здесь - нет, их просто нет. Если можно, передайте пожалуйста на производство тому человеку или нескольким, кто занимался моим заказом, огромное спасибо, я не раз помянул их сегодня добрым словом, да и весь коллектив. Спасибо вам, друзья! Желаю всем здоровья и успехов во всех начинаниях.\nПару моментов, которые нисколько не омрачили моей радости, но возможно пригодятся Вам в дальнейшей работе: \n1. Подголовники, как я и ожидал не подошли, они на послерестайловую модель 2013 года выпуска, часть Сузуки Джимни в 2012 году шли со старыми в виде пенополиуретановой рамки, часть с новыми. Старые значительно лучше на вид и одевать чехлы я на них в общем-то и не собирался, ну Вы помните, возможно, я при заказе еще это Вам сказал. \n2. DPD? Меня немного удивило, что вы пользуетесь этой транспортной компанией, хотя доставка быстрая и дешевая, но у нас про неё почти никто ничего не знает. Мне понравились работники, очень приветливые, но работают с 9 до 18, а касса до 17-30, - это напрягает, в выходные не работают. Расположение склада ужасное, в самом поганом районе нашего города. Я работаю с 8 до 18 в диаметрально противоположной точке города, забрать груз для меня было несколько проблематично, пришлось отпрашиваться с работы. С почтой России было бы проще, хоть и дольше и дороже, а выбора способа доставки мне не предложили или я сам что-то не доделал при заказе на сайте.\nНу да ладно, это всё мелочи, просто я привык их замечать. Внешний вид красного Сузуки Джимни с красно-чёрными чехлами изумительный. Я очень рад! Рад, что сделал заказ в вашей компании. Качество, точность, скорость, надёжность и пунктуальность - это про Вас. Дарите людям радость и дальше.","car":"Сузуки Джимни"},{"b":"lada","n":"Иван","c":"Омск","d":"16.06.2015","t":"Чехлами доволен. Рекомендую всем","car":"Ваз 2112","ph":["iblock/901/B2ua0iAKhZU.jpg","iblock/275/cDUp6EAO-Wo.jpg","iblock/abb/FarbnLqREhQ.jpg","iblock/52d/x_mg2Vy0dgY.jpg","iblock/60d/NKaDfFG0vzI.jpg"]},{"b":"skoda","f":"skoda-octavia","n":"Халяпин Валерий Иванович","c":"Кемерово","d":"29.10.2013","t":"Заказывал у Вас чехлы для Skoda Octavia. Изготовлено было все в оговоренные сроки и все хорошо подошло. Цена чехлов тоже приемлемая, на 40 % ниже чем в магазине. Рекомендую знакомым тоже заказать у Вас чехлы на машину. Спасибо за качественный товар!","car":"Skoda Octavia A-5","ph":["iblock/35b/2.jpg","iblock/dc2/1.jpg","iblock/395/3.jpg","iblock/5a7/4.jpg"]},{"b":"toyota","f":"toyota-rav4","n":"Александр Гребенюк","c":"Сухой Лог","d":"22.10.2013","t":"Доброго времени суток уважаемые! Наконец то одел чехлы в полном объеме. Очень понравились и мне и супруге. Салон автомобиля стал богаче. Добротно сшиты, а главное цена. Не покупать же РАФика с кожанным салоном дорогой комплектации да ещё с ненужными опциями. Фирма оперативно приняла заказ и его исполнила. Чехлы были доставлены прямо в квартиру. Вообщем посоветую своим друзьям. Жаль только, что не на все модели чехлы шьют, а конкретно на Мазду СХ-5. А так всё супер. Уважаемые автолюбители заказывайте чехлы не пожалеете. Всем привет из Сухого Лога, Свердловской области!","car":"Toyota Rav 4","ph":["iblock/ae1/2.jpg","iblock/37f/1.jpg","iblock/0b6/6.jpg","iblock/71a/7.jpg"]},{"b":"volkswagen","f":"volkswagen-polo","n":"Алена","c":"Новосибирск","d":"08.10.2013","t":"Чехлы подошли хорошо. Экокожа выглядит гораздо лучше чем на фото на сайте. Очень довольна покупкой. Автомобиль поменялся, выглядит очень дорого. Отдельное спасибо вежливым менеджерам автомагазина!","car":"Volkswagen Polo","ph":["iblock/145/1.jpg","iblock/107/2.jpg","iblock/117/3.jpg","iblock/6ca/4.jpg","iblock/38b/5.jpg","iblock/0a7/6.jpg","iblock/08b/7.jpg"]},{"b":"chevrolet","f":"chevrolet-niva","n":"Сергей Архипов","c":"Новосибирск","d":"03.10.2013","t":"Купил по рекомендации друга авточехлы на вашем сайте, одели за пару часов, чехлы сидят хорошо, жене и друзьям очень нравятся. Салон стал новым и дорогим. Соседа уже направил покупать чехлы на том же сайте. Еще раз спасибо за чехлы!","car":"Chevrolet Niva","ph":["iblock/20b/2.jpg","iblock/921/1.jpg","iblock/3d2/3.jpg","iblock/a07/4.jpg","iblock/fab/5.jpg","iblock/297/6.jpg","iblock/00e/7.jpg"]},{"b":"honda","f":"honda-cr-v","n":"Ираида Мишурко","c":"Ярославль","d":"30.09.2013","t":"Чехлы мы одели, все очень хорошо подошло. Спасибо!","car":"Honda CR-V","ph":["iblock/724/honda crv.JPG","iblock/535/honda crv (2).JPG","iblock/1c2/honda crv (4).JPG","iblock/c6f/honda crv (6).JPG","iblock/eeb/honda crv (7).JPG","iblock/8fe/honda crv (3).JPG","iblock/2f0/honda crv (5).JPG"]},{"b":"renault","f":"renault-duster","n":"Валерий Валеев","c":"Юрга","d":"30.09.2013","t":"Очень понравились чехлы. Сели как влитые. Качество отличное! Спасибо! А с учетом цены, нравятся еще больше.","car":"Renault Daster","ph":["iblock/50e/17.jpg","iblock/c5e/15.jpg","iblock/1a7/16.jpg"]},{"b":"mitsubishi","f":"mitsubishi-lancer","n":"Виталий Викторович","c":"Новосибирск","d":"30.09.2013","t":"Увидел у соседа чехлы из экокожи и мне они понравились. Отзывы соседа о них, услышал только положительные. Заказал и остался доволен оперативным обслуживанием и качеством товара. Установил без проблем. Чехлы не требуют особого ухода, спина не потеет, очень прочные, смотрятся очень стильно и дорого. И если чем-то не устроят, их можно сдать. Всем моим друзьям, так же чехлы понравились. У всех появилось желание приобрести такие же.","car":"Mitsubishi Lancer X","ph":["iblock/b24/4.jpg","iblock/4fe/1.jpg","iblock/de7/2.jpg","iblock/8a6/3.jpg"]},{"b":"daewoo","f":"daewoo-nexia","n":"Алексей Райзих","c":"Тюмень","d":"30.09.2013","t":"Чехлы одел за два часа, все подошло, мне нравится. Благодарю вас!","car":"Deawoo Nexia","ph":["iblock/a82/20.jpg","iblock/961/21.jpg","iblock/839/23.jpg","iblock/136/25.jpg"]},{"b":"ssangyong","f":"ssangyong-kyron","n":"Булдыгин Виталий","c":"Стрежевой","d":"27.09.2013","t":"Доброго времени суток. Вчера установил чехлы, одевал их на снятых с машины сидений, получилось очень хорошо. Ещё раз спасибо.","car":"Ssang_Yong Kyron","ph":["iblock/022/ssang.jpg","iblock/2a5/ssang (2).jpg","iblock/695/ssang (3).jpg","iblock/025/ssang (4).jpg"]}];
